		public int ChapterIndex
		{
			get
			{
				if (StoryId == null)
				{
					return -1;
				}
				EpochModel[] epochs = StoryModel.Get(StringHelper.Slugify(StoryId)).Epochs;
				for (int i = 0; i < epochs.Length; i++)
				{
					if (epochs[i].Id == Id)
					{
						return i + 1;
					}
				}
				return -1;
			}
		}

