	public class EpochIdListConverter : JsonConverter<List<string>>
	{
		public override List<string> Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
		{
			List<string> list = new List<string>();
			if (reader.TokenType != JsonTokenType.StartArray)
			{
				throw new JsonException($"Expected start of array for epoch ID list, but got {reader.TokenType}");
			}
			while (reader.Read() && reader.TokenType != JsonTokenType.EndArray)
			{
				string text = reader.GetString();
				if (text != null)
				{
					int num = text.IndexOf('.');
					if (num >= 0)
					{
						string text2 = text;
						int num2 = num + 1;
						text = text2.Substring(num2, text2.Length - num2);
					}
					list.Add(text);
				}
			}
			return list;
		}

		public override void Write(Utf8JsonWriter writer, List<string> value, JsonSerializerOptions options)
		{
			writer.WriteStartArray();
			foreach (string item in value)
			{
				writer.WriteStringValue(item);
			}
			writer.WriteEndArray();
		}
	}
	public class JsonSerializeConditionAttribute : Attribute
	{
		public readonly SerializationCondition defaultBehaviour;

		public JsonSerializeConditionAttribute(SerializationCondition defaultBehaviour)
		{
			this.defaultBehaviour = defaultBehaviour;
		}

		public static void CheckJsonSerializeConditionsModifier(JsonTypeInfo typeInfo)
		{
			if (typeInfo.Kind != JsonTypeInfoKind.Object)
			{
				return;
			}
			foreach (JsonPropertyInfo property in typeInfo.Properties)
			{
				JsonSerializeConditionAttribute attr = property.AttributeProvider?.GetCustomAttributes(inherit: true).OfType<JsonSerializeConditionAttribute>().FirstOrDefault();
				if (attr == null)
				{
					continue;
				}
				ICustomAttributeProvider attributeProvider = property.AttributeProvider;
				MemberInfo memberInfo = attributeProvider as MemberInfo;
				if ((object)memberInfo != null)
				{
					property.ShouldSerialize = (object _, object? c) => attr.defaultBehaviour.ShouldSerialize(c, memberInfo);
				}
			}
		}
	}
	public class ModelIdRunSaveConverter : JsonConverter<ModelId>
	{
		public override ModelId Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
		{
			string text = reader.GetString();
			if (text != null)
			{
				return ModelId.Deserialize(text);
			}
			return ModelId.none;
		}

		public override void Write(Utf8JsonWriter writer, ModelId value, JsonSerializerOptions options)
		{
			writer.WriteStringValue(value.ToString());
		}
	}
