	public struct ActWinMetric(string actId, bool win)
	{
		public readonly string act = actId;

		public readonly bool win = win;
	}
	public struct AncientMetric
	{
		public readonly string picked;

		public readonly List<string> skipped;

		public AncientMetric(MapPointHistoryEntry entry, PlayerMapPointHistoryEntry playerEntry)
		{
			AncientChoiceHistoryEntry ancientChoiceHistoryEntry = playerEntry.AncientChoices.FirstOrDefault((AncientChoiceHistoryEntry o) => o.WasChosen);
			if (ancientChoiceHistoryEntry == null)
			{
				throw new InvalidOperationException($"Failed to find chosen ancient choice! {entry.Rooms.First().ModelId} {playerEntry.PlayerId}");
			}
			picked = ancientChoiceHistoryEntry.TextKey;
			skipped = (from o in playerEntry.AncientChoices
				where !o.WasChosen
				select o.TextKey).ToList();
		}
	}
	public struct CardChoiceMetric
	{
		public readonly List<string> picked = new List<string>();

		public readonly List<string> skipped = new List<string>();

		public CardChoiceMetric(List<CardChoiceHistoryEntry> choices)
		{
			foreach (CardChoiceHistoryEntry choice in choices)
			{
				if (choice.wasPicked)
				{
					picked.Add(choice.Card.Id.Entry);
				}
				else
				{
					skipped.Add(choice.Card.Id.Entry);
				}
			}
		}
	}
	public struct EncounterMetric(string id, int damage, int turns)
	{
		public readonly string id = id;

		public readonly int damage = Math.Clamp(damage, 0, 100);

		public readonly int turns = turns;
	}
	public struct EventChoiceMetric
	{
		public readonly string id;

		public readonly string act;

		public readonly string picked;

		public EventChoiceMetric(MapPointHistoryEntry entry, ulong playerId, SerializableActModel actModel)
		{
			id = entry.Rooms.First().ModelId.Entry;
			act = actModel.Id.Entry;
			LocString title = entry.GetEntry(playerId).EventChoices.Last().Title;
			picked = title.LocEntryKey.Split(".")[^2];
		}
	}
