		{
			switch (branch)
			{
			case PlatformBranch.None:
				return "none";
			case PlatformBranch.DevTest:
				return "dev-test";
			case PlatformBranch.PrivateBeta:
				return "private-beta";
			case PlatformBranch.PublicBeta:
				return "public-beta";
			case PlatformBranch.Production:
				return "public";
			default:
			{
				global::<PrivateImplementationDetails>.ThrowSwitchExpressionException(branch);
				string result = default(string);
				return result;
			}
