		NetworkConfig = 3004,
		LocalRights = 3005,
		LocalMax = 3999,
		RemoteTimeout = 4001,
		BadCrypt = 4002,
		BadCert = 4003,
		NotLoggedIn = 4004,
		NotRunningApp = 4005,
		BadProtocolVersion = 4006,
