			if (_branch.HasValue)
			{
				return _branch.Value;
			}
			string text = default(string);
			if (!SteamApps.GetCurrentBetaName(ref text, 128))
			{
				_branch = PlatformBranch.Production;
			}
			else
			{
				PlatformBranch? branch = PlatformBranchExtensions.FromName(text);
				if (branch.HasValue)
				{
					_branch = branch;
				}
				else
				{
					Log.Error($"User is on Steam beta branch {text} which could not be mapped to any {"PlatformBranch"}! Defaulting to None");
