namespace MegaCrit.Sts2.Core.Multiplayer.Serialization
{
	internal static class BitSerializationUtil
	{
		public static byte GetByteMask(int bits, int startBit)
		{
			if (bits > 8 || startBit + bits > 8)
			{
				throw new InvalidOperationException();
			}
			return (byte)((1 << bits) - 1 << startBit);
		}

		public static byte GetBitsAtPosition(byte[] bytes, int bitPosition, int bitsToObtain)
		{
			int num = bitPosition / 8;
			int num2 = bitPosition % 8;
			if (bitsToObtain > 8)
			{
				throw new InvalidOperationException();
			}
			if (num2 == 0)
			{
				return (byte)(bytes[num] & GetByteMask(bitsToObtain, 0));
			}
			int num3 = 8 - num2;
			if (bitsToObtain <= num3)
			{
				return (byte)((bytes[num] >> num2) & GetByteMask(bitsToObtain, 0));
			}
			byte b = (byte)(bytes[num] >> num2);
			byte byteMask = GetByteMask(num3, 0);
			byte b2 = (byte)(bytes[num + 1] << num3);
			byte byteMask2 = GetByteMask(bitsToObtain - num3, num3);
			byte b3 = (byte)((b & byteMask) | (b2 & byteMask2));
			return (byte)(b3 & GetByteMask(bitsToObtain, 0));
		}

		public static void WriteBytes(byte[] originBuffer, byte[] destinationBuffer, int destinationBitPosition, int totalBitsToWrite)
		{
			int num3;
			for (int i = 0; i < totalBitsToWrite; i += num3)
			{
				int num = (destinationBitPosition + i) / 8;
				int num2 = (destinationBitPosition + i) % 8;
				num3 = Mathf.Min(totalBitsToWrite - i, 8 - num2);
				byte bitsAtPosition = GetBitsAtPosition(originBuffer, i, num3);
				byte b = destinationBuffer[num];
				byte byteMask = GetByteMask(num2, 0);
				byte byteMask2 = GetByteMask(num3, num2);
				byte b2 = (byte)(bitsAtPosition << num2);
				byte b3 = (byte)((b & byteMask) | (b2 & byteMask2));
				destinationBuffer[num] = b3;
			}
		}

		public static void ReadBits(byte[] originBuffer, int originBitPosition, byte[] destinationBuffer, int totalBitsToRead)
		{
			int num3;
			for (int i = 0; i < totalBitsToRead; i += num3)
			{
				int num = i / 8;
				int num2 = i % 8;
				num3 = Mathf.Min(totalBitsToRead - i, 8 - num2);
				byte bitsAtPosition = GetBitsAtPosition(originBuffer, originBitPosition + i, num3);
				byte b = destinationBuffer[num];
				byte byteMask = GetByteMask(num2, 0);
				byte byteMask2 = GetByteMask(num3, num2);
				byte b2 = (byte)(bitsAtPosition << num2);
				byte b3 = (byte)((b & byteMask) | (b2 & byteMask2));
				destinationBuffer[num] = b3;
			}
		}
	}
	public static class ContentSorter<TIdType> where TIdType : IComparable<TIdType>
	{
		public struct Item
		{
			public Type type;

			public TIdType id;

			public Mod? mod;

			public override string ToString()
			{
				return $"{type} {id} {mod?.manifest?.id}";
			}
		}

		public static List<Item> Sort(IEnumerable<Type> types, Func<Type, TIdType> getId, bool affectsGameplayAtEnd = true)
		{
			if (AssemblyInfo.ModMap == null)
			{
				throw new InvalidOperationException("ContentSorter called before AssemblyInfo was initialized. This is not allowed.");
			}
			List<Item> list = new List<Item>();
			foreach (Type type in types)
			{
				bool isBaseGame;
				Mod mod = AssemblyInfo.ModForType(type, out isBaseGame);
				if (mod == null && !isBaseGame)
				{
					Log.Error($"Attempting to register type {type} in assembly {type.Assembly}, but it is not associated with any mod! You may need to call {"ModManager"}.{"AssociateAssemblyWithMod"} to manually register the assembly. Type sorting may break because of this, causing errors in multiplayer.");
				}
				list.Add(new Item
				{
					type = type,
					id = getId(type),
					mod = mod
				});
			}
			Sort(list, affectsGameplayAtEnd);
			return list;
		}

		public static List<Item> Sort(List<Item> items, bool affectsGameplayAtEnd = true)
		{
			items.Sort(delegate(Item p1, Item p2)
			{
				if (affectsGameplayAtEnd)
				{
					bool value = p1.mod?.manifest?.affectsGameplay ?? true;
					int num = (p2.mod?.manifest?.affectsGameplay ?? true).CompareTo(value);
					if (num != 0)
					{
						return num;
					}
				}
				ref TIdType id = ref p1.id;
				TIdType id2 = p2.id;
				int num2 = id.CompareTo(id2);
				if (num2 != 0)
				{
					return num2;
				}
				if (p1.mod != null && p2.mod == null)
				{
					return 1;
				}
				if (p1.mod == null && p2.mod != null)
				{
					return -1;
				}
				if (p1.mod == null && p2.mod == null)
				{
					return 0;
				}
				int num3 = string.CompareOrdinal(p1.mod.manifest.id, p2.mod.manifest.id);
				if (num3 != 0)
				{
					return num3;
				}
				int num4 = string.CompareOrdinal(p1.type.FullName, p2.type.FullName);
				if (num4 != 0)
				{
					return num4;
				}
				string fullName = p1.type.Assembly.FullName;
				string fullName2 = p2.type.Assembly.FullName;
				int num5 = string.CompareOrdinal(fullName, fullName2);
				return (num5 != 0) ? num5 : 0;
			});
			return items;
		}
	}
