			}
			Vector2 val = _cursorTranslator?.GetNetPositionFromScreenPosition(mouseScreenPos) ?? NetCursorHelper.GetNormalizedPosition(mouseScreenPos, rootControl);
			_syncMessageToSend.netMousePos = val;
			orCreateStateForPlayer.netMousePosition = val;
			this.StateChanged?.Invoke(_netService.NetId);
