			//IL_005a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0046: Unknown result type (might be due to invalid IL or missing references)
			PeerInputState orCreateStateForPlayer = GetOrCreateStateForPlayer(playerId);
			Vector2 val = (orCreateStateForPlayer.isUsingController ? orCreateStateForPlayer.controllerFocusPosition : orCreateStateForPlayer.netMousePosition);
			if (_cursorTranslator == null)
			{
				return NetCursorHelper.GetControlSpacePosition(val, rootControl);
			}
			Vector2 screenPositionFromNetPosition = _cursorTranslator.GetScreenPositionFromNetPosition(val);
			if (rootControl == null)
			{
				if (TestMode.IsOn)
				{
					return screenPositionFromNetPosition;
				}
