				"die" => _dieMoveName.GetRawText(), 
				"hurt" => _hurtMoveName.GetRawText(), 
				"revive" => _reviveMoveName.GetRawText(), 
				"stun" => _stunMoveName.GetRawText(), 
				_ => animId, 
			}));
			result.displayName = text;
			result.sfx = sfx;
