		{
			return true;
		}

		private IEnumerable<string> GetAllMoves(MonsterMoveStateMachine machine)
		{
			foreach (KeyValuePair<string, MonsterState> state in machine.States)
			{
				if (state.Value is MoveState)
				{
					yield return state.Key;
				}
			}
		}

