		{
			get
			{
				if (IsUsedUp)
				{
					return false;
				}
				if (HasUponPickupEffect)
				{
					return false;
				}
				if (IsMelted)
				{
					return false;
				}
				if (SpawnsPets)
				{
					return false;
				}
				RelicRarity rarity = Rarity;
				if ((rarity == RelicRarity.Starter || (uint)(rarity - 6) <= 1u) ? true : false)
				{
					return false;
				}
				return true;
			}
		}

