		public override RelicRarity Rarity => RelicRarity.Ancient;

		public override bool HasUponPickupEffect => true;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new CardsVar(15),
			new StringVar("Character")
		});

		public override async Task AfterObtained()
		{
			if (CharacterId == null)
			{
				Log.Error("Sea Glass was obtained without a character ID assigned! This could be a bug, or the player could have used the console. Defaulting to Ironclad");
				CharacterId = ModelDb.Character<Ironclad>().Id;
			}
			int cardCount = base.DynamicVars.Cards.IntValue / 3;
			CardCreationOptions options = CardCreationOptions.ForNonCombatWithUniformOdds(new global::<>z__ReadOnlySingleElementList<CardPoolModel>(Character.CardPool), (CardModel c) => c.Rarity == CardRarity.Common).WithFlags(CardCreationFlags.NoRarityModification | CardCreationFlags.NoCardPoolModifications);
			CardCreationOptions options2 = CardCreationOptions.ForNonCombatWithUniformOdds(new global::<>z__ReadOnlySingleElementList<CardPoolModel>(Character.CardPool), (CardModel c) => c.Rarity == CardRarity.Uncommon).WithFlags(CardCreationFlags.NoRarityModification | CardCreationFlags.NoCardPoolModifications);
			CardCreationOptions options3 = CardCreationOptions.ForNonCombatWithUniformOdds(new global::<>z__ReadOnlySingleElementList<CardPoolModel>(Character.CardPool), (CardModel c) => c.Rarity == CardRarity.Rare).WithFlags(CardCreationFlags.NoRarityModification | CardCreationFlags.NoCardPoolModifications);
			List<CardCreationResult> first = CardFactory.CreateForReward(base.Owner, cardCount, options).ToList();
			List<CardCreationResult> second = CardFactory.CreateForReward(base.Owner, cardCount, options2).ToList();
			List<CardCreationResult> second2 = CardFactory.CreateForReward(base.Owner, cardCount, options3).ToList();
			List<CardCreationResult> list = first.Concat(second).Concat(second2).ToList();
			foreach (CardModel item in await CardSelectCmd.FromSimpleGridForRewards(prefs: new CardSelectorPrefs(RelicModel.L10NLookup(base.Id.Entry + ".selectionScreenPrompt"), 0, list.Count), context: new BlockingPlayerChoiceContext(), cards: list, player: base.Owner))
			{
				CardCmd.PreviewCardPileAdd(await CardPileCmd.Add(item, PileType.Deck));
			}
		}
	}
