		public override RelicRarity Rarity => RelicRarity.Ancient;

		public override bool ShowCounter => CombatManager.Instance.IsInProgress;

		public override int DisplayAmount
		{
			get
			{
				if (!base.IsCanonical)
				{
					return _cardsPlayedThisTurn;
				}
				return 0;
			}
		}

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new CardsVar(6),
			new EnergyVar(1)
		});

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.ForEnergy(this));

		private bool ShouldPreventCardPlay => _cardsPlayedThisTurn >= base.DynamicVars.Cards.IntValue;

		public override decimal ModifyMaxEnergy(Player player, decimal amount)
		{
			if (player != base.Owner)
			{
				return amount;
			}
			return amount + base.DynamicVars.Energy.BaseValue;
