		protected override IEnumerable<IHoverTip> ExtraHoverTips => HoverTipFactory.FromEnchantment<Swift>(base.DynamicVars["SwiftAmount"].IntValue);

		public override bool TryModifyCardRewardOptionsLate(Player player, List<CardCreationResult> cardRewards, CardCreationOptions options)
		{
			if (player != base.Owner)
			{
				return false;
			}
			Swift canonicalSwift = ModelDb.Enchantment<Swift>();
			List<CardCreationResult> list = cardRewards.Where((CardCreationResult r) => canonicalSwift.CanEnchant(r.Card)).ToList();
			if (list.Count == 0)
			{
				return false;
			}
			CardCreationResult cardCreationResult = base.Owner.RunState.Rng.Niche.NextItem(list);
			if (cardCreationResult == null)
			{
				return false;
			}
			CardModel card = base.Owner.RunState.CloneCard(cardCreationResult.Card);
			CardCmd.Enchant<Swift>(card, base.DynamicVars["SwiftAmount"].BaseValue);
			cardCreationResult.ModifyCard(card, this);
			return true;
		}
	}
	public sealed class WingedBoots : RelicModel
	{
		private const string _roomsKey = "Rooms";

		private const int _roomCount = 3;

		private int _timesUsed;

		public override RelicRarity Rarity => RelicRarity.Ancient;

		public override bool IsUsedUp => TimesUsed >= 3;

		public override bool ShowCounter => !IsUsedUp;

		public override int DisplayAmount => 3 - TimesUsed;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new DynamicVar("Rooms", 3m));

		[SavedProperty]
		public int TimesUsed
		{
			get
			{
				return _timesUsed;
			}
			set
			{
				AssertMutable();
				_timesUsed = value;
				base.DynamicVars["Rooms"].BaseValue = 3 - _timesUsed;
				InvokeDisplayAmountChanged();
				CheckIfUsedUp();
			}
		}

		public override bool IsAllowed(IRunState runState)
		{
			return runState.Players.Count == 1;
		}

		public override bool ShouldAllowFreeTravel()
		{
			return !IsUsedUp;
		}

		public override Task AfterRoomEntered(AbstractRoom room)
		{
			if (IsUsedUp)
			{
				return Task.CompletedTask;
			}
			if (base.Owner.RunState.CurrentRoomCount > 1)
			{
				return Task.CompletedTask;
			}
			if (!(base.Owner.RunState is RunState runState))
			{
				return Task.CompletedTask;
			}
			if (runState.VisitedMapCoords.Count <= 1)
			{
				return Task.CompletedTask;
			}
			IReadOnlyList<MapCoord> visitedMapCoords = runState.VisitedMapCoords;
			MapCoord coord = visitedMapCoords[visitedMapCoords.Count - 2];
			MapPoint point = runState.Map.GetPoint(coord);
			if (point == null)
			{
				return Task.CompletedTask;
			}
			MapPoint currentMapPoint = base.Owner.RunState.CurrentMapPoint;
			if (currentMapPoint == null)
			{
				return Task.CompletedTask;
			}
			if (point.Children.Contains(currentMapPoint))
			{
				return Task.CompletedTask;
			}
			TimesUsed++;
			return Task.CompletedTask;
		}

		private void CheckIfUsedUp()
		{
			if (IsUsedUp)
			{
				base.Status = RelicStatus.Disabled;
			}
		}
	}
