	public sealed class DoomPower : PowerModel
	{
		public override PowerType Type => PowerType.Debuff;

		public override PowerStackType StackType => PowerStackType.Counter;

		public override Color AmountLabelColor => PowerModel._normalAmountLabelColor;

		public static async Task DoomKill(IReadOnlyList<Creature> creatures)
		{
			if (creatures.Count == 0)
			{
				return;
			}
			ICombatState combatState = creatures.First().CombatState;
			foreach (Creature creature in creatures)
			{
				await PlayVfx(creature);
				await CreatureCmd.Kill(creature);
			}
			await Hook.AfterDiedToDoom(combatState, creatures);
		}

		public static IReadOnlyList<Creature> GetDoomedCreatures(IReadOnlyList<Creature> creatures)
		{
			return creatures.Where((Creature c) => c.GetPower<DoomPower>()?.IsOwnerDoomed() ?? false).ToList();
		}

		public override async Task BeforeSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			if (side != CombatSide.Player && ShouldDoomTrigger(participants))
			{
				await DoomKill(GetDoomedCreatures(side));
			}
		}

		public override async Task AfterSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			if (side != CombatSide.Enemy && ShouldDoomTrigger(participants))
			{
				await DoomKill(GetDoomedCreatures(side));
			}
		}

		private bool ShouldDoomTrigger(IEnumerable<Creature> participants)
		{
			if (CombatManager.Instance.IsOverOrEnding)
			{
				return false;
			}
			if (!participants.Contains(base.Owner))
			{
				return false;
			}
			if (base.Owner.IsDead)
			{
				return false;
			}
			if (!IsOwnerDoomed())
			{
				return false;
			}
			IReadOnlyList<Creature> doomedCreatures = GetDoomedCreatures(base.Owner.Side);
			if (doomedCreatures.First() != base.Owner)
			{
				return false;
			}
			return true;
		}

		private static async Task PlayVfx(Creature creature)
		{
			NCreature nCreature = NCombatRoom.Instance?.GetCreatureNode(creature);
			if (nCreature == null)
			{
				return;
			}
			bool flag = false;
			if (creature.IsMonster)
			{
				flag = Hook.ShouldDie(creature.Player?.RunState ?? creature.CombatState.RunState, creature.CombatState, creature, out AbstractModel _) && creature.Monster.ShouldDisappearFromDoom;
			}
			StartDoomAnim(nCreature, flag);
			NDoomOverlayVfx orCreate = NDoomOverlayVfx.GetOrCreate();
			if (orCreate != null && !((Node)orCreate).IsInsideTree())
			{
				((Node)(object)NCombatRoom.Instance.CombatVfxContainer).AddChildSafely((Node?)(object)orCreate);
			}
			List<Creature> source = (from c in creature.CombatState.GetTeammatesOf(creature)
				where c.IsAlive
				select c).ToList();
			if (flag)
			{
				if (source.Count() != 1 || source.First() != creature)
				{
					await Cmd.Wait(0.25f);
				}
				else
				{
					await Cmd.Wait(1.5f);
				}
			}
		}

		private IReadOnlyList<Creature> GetDoomedCreatures(CombatSide side)
		{
			return GetDoomedCreatures(base.CombatState.GetCreaturesOnSide(side));
		}

		private bool IsOwnerDoomed()
		{
			return base.Owner.CurrentHp <= base.Amount;
		}

		private static void StartDoomAnim(NCreature creature, bool shouldDie)
		{
			//IL_00f0: Unknown result type (might be due to invalid IL or missing references)
			//IL_00fb: Unknown result type (might be due to invalid IL or missing references)
			//IL_0038: Unknown result type (might be due to invalid IL or missing references)
			Task task = null;
			if (shouldDie)
			{
				creature.Entity.Monster?.OnDieToDoom();
				creature.DisableInteractionForDeath();
				Tween val = creature.AnimDisableUi();
				val.TweenCallback(Callable.From((Action)creature.QueueFreeSafely));
				task = WaitForTween(val, (Node)(object)creature);
				if (creature.SpineAnimation.IsValid)
				{
					creature.SetAnimationTrigger("Hit");
					using MegaTrackEntry megaTrackEntry = creature.SpineAnimation.GetCurrentTrack();
					if (megaTrackEntry?.GetAnimationName() == "hurt")
					{
						float trackTime = creature.Entity.Monster?.HurtAnimationTrackOffsetForDoom ?? 0.1f;
						megaTrackEntry.SetTrackTime(trackTime);
						megaTrackEntry.SetTimeScale(0f);
					}
				}
				NCombatRoom.Instance?.RemoveCreatureNode(creature);
			}
			NDoomVfx nDoomVfx = NDoomVfx.Create(creature.Visuals, creature.Hitbox.GlobalPosition, creature.Hitbox.Size, shouldDie);
			((Node)(object)NCombatRoom.Instance?.CombatVfxContainer).AddChildSafely((Node?)(object)nDoomVfx);
			if (shouldDie)
			{
				global::<>y__InlineArray2<Task> buffer = default(global::<>y__InlineArray2<Task>);
				buffer[0] = task;
				buffer[1] = nDoomVfx.VfxTask;
				creature.DeathAnimationTask = Task.WhenAll(buffer);
			}
		}

		private static async Task WaitForTween(Tween t, Node owner)
		{
			await t.AwaitFinished(owner);
		}
	}
