	public sealed class PainfulStabsPower : PowerModel
	{
		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => HoverTipFactory.FromCardWithCardHoverTips<Wound>();

		public override bool ShouldPowerBeRemovedAfterOwnerDeath()
		{
			return false;
		}

		public override bool ShouldCreatureBeRemovedFromCombatAfterDeath(Creature creature)
		{
			return creature != base.Owner;
		}

		public override async Task AfterAttack(PlayerChoiceContext choiceContext, AttackCommand command)
		{
			if (command.Attacker != base.Owner || command.TargetSide == base.Owner.Side || !command.DamageProps.IsPoweredAttack())
			{
				return;
			}
			List<DamageResult> list = command.Results.SelectMany((List<DamageResult> r) => r).ToList();
			if (!list.Any((DamageResult r) => r.UnblockedDamage > 0))
			{
				return;
			}
			Dictionary<Creature, List<DamageResult>> damageResultsByCreature = new Dictionary<Creature, List<DamageResult>>();
			foreach (DamageResult item in list)
			{
				if (item.Receiver.IsPlayer)
				{
					if (!damageResultsByCreature.ContainsKey(item.Receiver))
					{
						damageResultsByCreature.Add(item.Receiver, new List<DamageResult>());
					}
					damageResultsByCreature[item.Receiver].Add(item);
				}
			}
			bool anyWoundApplied = false;
			foreach (Creature key in damageResultsByCreature.Keys)
			{
				int num = damageResultsByCreature[key].Count((DamageResult r) => r.UnblockedDamage > 0);
				anyWoundApplied = anyWoundApplied || num > 0;
				await CardPileCmd.AddToCombatAndPreview<Wound>(key, PileType.Discard, base.Amount * num, null);
			}
			if (anyWoundApplied)
			{
				Flash();
			}
		}
	}
	public sealed class PaleBlueDotPower : PowerModel
	{
		private class Data
		{
			public bool alreadyActivatedThisTurn;
		}

		public const string cardPlayThresholdKey = "CardPlay";

		public const int cardPlayThresholdValue = 5;

		public override int DisplayAmount => Math.Max(0, 5 - AttacksPlayedThisTurn);

		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new DynamicVar("CardPlay", 5m));

		private int AttacksPlayedThisTurn => CombatManager.Instance.History.CardPlaysFinished.Count((CardPlayFinishedEntry c) => c.HappenedThisTurn(base.Owner.CombatState) && c.CardPlay.Player == base.Owner.Player);

		protected override object InitInternalData()
		{
			return new Data();
		}

		public override async Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (cardPlay.Card.Owner != base.Owner.Player)
			{
				return;
			}
			Data internalData = GetInternalData<Data>();
			if (!internalData.alreadyActivatedThisTurn)
			{
				InvokeDisplayAmountChanged();
				if (AttacksPlayedThisTurn >= 5)
				{
					internalData.alreadyActivatedThisTurn = true;
					await Cmd.Wait(0.5f);
					await PowerCmd.Apply<DrawCardsNextTurnPower>(choiceContext, base.Owner, base.Amount, base.Owner, null);
				}
			}
		}

		public override Task AfterSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			if (!participants.Contains(base.Owner))
			{
				return Task.CompletedTask;
			}
			Data internalData = GetInternalData<Data>();
			internalData.alreadyActivatedThisTurn = false;
			InvokeDisplayAmountChanged();
			return Task.CompletedTask;
		}
	}
	public sealed class PanachePower : PowerModel
	{
		private class Data
		{
			public bool alreadyApplied;
		}

		private const int _baseCardsLeft = 5;

		private const string _cardsLeftKey = "CardsLeft";

		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		public override int DisplayAmount => base.DynamicVars["CardsLeft"].IntValue;

		public override PowerInstanceType InstanceType => PowerInstanceType.Instanced;

