		public override async Task AfterPlayerTurnStart(PlayerChoiceContext choiceContext, Player player)
		{
			if (player != base.Owner.Player)
			{
				return;
			}
			Flash();
			if (TestMode.IsOn)
			{
				await DoDamage(choiceContext, base.CombatState.HittableEnemies);
			}
			else
			{
				List<Task> damageTasks = new List<Task>();
				NRollingBoulderVfx nRollingBoulderVfx = NRollingBoulderVfx.Create(base.CombatState.HittableEnemies, base.Amount);
				((GodotObject)nRollingBoulderVfx).Connect(NRollingBoulderVfx.SignalName.HitCreature, Callable.From<NCreature>((Action<NCreature>)delegate(NCreature c)
				{
					damageTasks.Add(DoDamage(choiceContext, new global::<>z__ReadOnlySingleElementList<Creature>(c.Entity)));
				}), 0u);
				SignalAwaiter val = ((GodotObject)nRollingBoulderVfx).ToSignal((GodotObject)(object)nRollingBoulderVfx, NRollingBoulderVfx.SignalName.Finished);
				NCombatRoom? instance = NCombatRoom.Instance;
				if (instance != null)
				{
					((GodotObject)instance.CombatVfxContainer).CallDeferred(MethodName.AddChild, (Variant[])(object)new Variant[1] { Variant.op_Implicit((GodotObject)(object)nRollingBoulderVfx) });
				}
				await val;
				await Task.WhenAll(damageTasks);
			}
			SetAmount(base.Amount + base.DynamicVars.Damage.IntValue);
		}

		private Task<IEnumerable<DamageResult>> DoDamage(PlayerChoiceContext choiceContext, IEnumerable<Creature> targets)
		{
