	public sealed class TheBombPower : PowerModel
	{
		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		public override PowerInstanceType InstanceType => PowerInstanceType.Instanced;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new DamageVar(40m, ValueProp.Unpowered));

		public void SetDamage(decimal damage)
		{
			AssertMutable();
			base.DynamicVars.Damage.BaseValue = damage;
		}

		public override async Task BeforeSideTurnEnd(PlayerChoiceContext choiceContext, CombatSide side, IEnumerable<Creature> participants)
		{
			if (!participants.Contains(base.Owner))
			{
				return;
			}
			if (base.Amount > 1)
			{
				await PowerCmd.Decrement(this);
				return;
			}
			Flash();
			await Cmd.CustomScaledWait(0.2f, 0.4f);
			foreach (Creature hittableEnemy in base.CombatState.HittableEnemies)
			{
				((Node)(object)NCombatRoom.Instance?.CombatVfxContainer).AddChildSafely((Node?)(object)NFireSmokePuffVfx.Create(hittableEnemy));
			}
			await Cmd.CustomScaledWait(0.2f, 0.4f);
			await CreatureCmd.Damage(choiceContext, base.CombatState.HittableEnemies, base.DynamicVars.Damage, base.Owner);
			await PowerCmd.Remove(this);
		}
	}
