	{
		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Counter;

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromPower<WeakPower>());

		public override decimal ModifyDamageMultiplicative(Creature? target, decimal amount, ValueProp props, Creature? dealer, CardModel? cardSource, CardPlay? cardPlay)
		{
			if (!props.IsPoweredAttack())
			{
				return 1m;
			}
			if (cardSource == null)
			{
				return 1m;
			}
			if (dealer != base.Owner && !base.Owner.Pets.Contains<Creature>(dealer))
			{
				return 1m;
			}
			if (target == null || !target.HasPower<WeakPower>())
			{
				return 1m;
			}
			return 1m + (decimal)base.Amount / 100m;
		}
	}
	public sealed class TrashToTreasurePower : PowerModel
