					OrbModel orb = OrbModel.GetRandomOrb(base.Owner.Player.RunState.Rng.CombatOrbGeneration).ToMutable();
					await OrbCmd.Channel(new ThrowingPlayerChoiceContext(), orb, base.Owner.Player);
				}
			}
		}
