	public sealed class MockResetCombatOnShufflePower : PowerModel
	{
		private bool _hasReset;

		public override bool IsMock => true;

		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Single;

		private bool HasReset
		{
			get
			{
				return _hasReset;
			}
			set
			{
				AssertMutable();
				_hasReset = value;
			}
		}

		public override Task AfterCardChangedPiles(CardModel card, PileType oldPileType, AbstractModel? clonedBy)
		{
			if (!HasReset && oldPileType == PileType.Discard)
			{
				CardPile? pile = card.Pile;
				if (pile != null && pile.Type == PileType.Draw)
				{
					HasReset = true;
					CombatManager.Instance.Reset(graceful: true);
					return Task.CompletedTask;
				}
			}
			return Task.CompletedTask;
		}
	}
	public sealed class MockRevivePower : PowerModel
	{
		private class Data
		{
			public bool isReviving;
		}

		public override bool IsMock => true;

		public override PowerType Type => PowerType.Buff;

		public override PowerStackType StackType => PowerStackType.Single;

		private bool IsReviving => GetInternalData<Data>().isReviving;

		protected override object InitInternalData()
		{
			return new Data();
		}

		public override decimal ModifyDamageMultiplicative(Creature? target, decimal amount, ValueProp props, Creature? dealer, CardModel? cardSource, CardPlay? cardPlay)
		{
			if (target != base.Owner)
			{
				return 1m;
			}
			if (!IsReviving)
			{
				return 1m;
			}
			return 0m;
		}

		public override bool TryModifyPowerAmountReceived(PowerModel canonicalPower, Creature target, decimal amount, Creature? applier, out decimal modifiedAmount)
		{
			modifiedAmount = amount;
			if (target != base.Owner)
			{
				return false;
			}
			if (!IsReviving)
			{
				return false;
			}
			return true;
		}

		public override bool ShouldAllowHitting(Creature creature)
		{
			return !IsReviving;
		}

		public override bool ShouldDie(Creature creature)
		{
			if (creature != base.Owner)
			{
				return true;
			}
			return false;
		}

		public override bool ShouldStopCombatFromEnding()
		{
			return true;
		}

		public override async Task AfterPreventingDeath(Creature creature)
		{
			if (creature == base.Owner)
			{
				GetInternalData<Data>().isReviving = true;
				await CreatureCmd.Heal(base.Owner, 1m, playAnim: false);
			}
		}
	}
