	public sealed class FoulPotion : PotionModel
	{
		public override PotionRarity Rarity => PotionRarity.Event;

		public override PotionUsage Usage => PotionUsage.AnyTime;

		public override TargetType TargetType
		{
			get
			{
				if (!CombatManager.Instance.IsInProgress)
				{
					return TargetType.TargetedNoCreature;
				}
				return TargetType.AllEnemies;
			}
		}

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[2]
		{
			new DamageVar(12m, ValueProp.Unpowered),
			new GoldVar(100)
		});

		public override bool PassesCustomUsabilityCheck
		{
			get
			{
				if (CombatManager.Instance.IsInProgress)
				{
					return true;
				}
				AbstractRoom currentRoom = base.Owner.RunState.CurrentRoom;
				if (currentRoom is MerchantRoom)
				{
					goto IL_0040;
				}
				if (currentRoom is EventRoom eventRoom)
				{
					EventModel canonicalEvent = eventRoom.CanonicalEvent;
					if (canonicalEvent is FakeMerchant)
					{
						goto IL_0040;
					}
				}
				bool flag = false;
				goto IL_0046;
				IL_0046:
				if (flag)
				{
					return GetFoulPotionMerchantTarget(currentRoom).button != null;
				}
				return false;
				IL_0040:
				flag = true;
				goto IL_0046;
			}
		}

		protected override async Task OnUse(PlayerChoiceContext choiceContext, Creature? target)
		{
			if (CombatManager.Instance.IsInProgress)
			{
				Creature creature = base.Owner.Creature;
				DamageVar damage = base.DynamicVars.Damage;
				await CreatureCmd.Damage(choiceContext, base.Owner.Creature.CombatState.Creatures.Where((Creature c) => !c.IsPet), damage.BaseValue, damage.Props, creature, null, null);
			}
			else if (base.Owner.RunState.CurrentRoom is MerchantRoom)
			{
				NMerchantRoom nMerchantRoom = NRun.Instance?.MerchantRoom;
				if (nMerchantRoom != null)
				{
					ShowPotionVfx(nMerchantRoom.MerchantButton);
					nMerchantRoom.FoulPotionThrown(this);
				}
				await PlayerCmd.GainGold(base.DynamicVars.Gold.BaseValue, base.Owner);
			}
			else
			{
				if (!(base.Owner.RunState.CurrentRoom is EventRoom eventRoom) || !(eventRoom.CanonicalEvent is FakeMerchant))
				{
					return;
				}
				EventModel localMutableEvent = eventRoom.LocalMutableEvent;
				if (localMutableEvent == null || !(localMutableEvent.Node is NFakeMerchant nFakeMerchant))
				{
					return;
				}
				ShowPotionVfx(nFakeMerchant.MerchantButton);
				List<Task> list = new List<Task>();
				foreach (Player player in base.Owner.RunState.Players)
				{
					FakeMerchant fakeMerchant = (FakeMerchant)RunManager.Instance.EventSynchronizer.GetEventForPlayer(player);
					list.Add(fakeMerchant.FoulPotionThrown(this));
				}
				await Task.WhenAll(list);
			}
		}

		private void ShowPotionVfx(NMerchantButton? merchantButton)
		{
			//IL_0038: Unknown result type (might be due to invalid IL or missing references)
			if (!TestMode.IsOn && merchantButton != null)
			{
				string scenePath = SceneHelper.GetScenePath("vfx/vfx_slime_impact");
				Node2D val = PreloadManager.Cache.GetScene(scenePath).Instantiate<Node2D>((GenEditState)0);
				((Node)merchantButton).GetParent().AddChildSafely((Node?)(object)val);
				val.GlobalPosition = ((Control)merchantButton).GlobalPosition;
			}
		}

		public static (NMerchantButton? button, Control? screenContext) GetFoulPotionMerchantTarget(AbstractRoom room)
		{
			if (room.RoomType == RoomType.Shop)
			{
				NMerchantRoom instance = NMerchantRoom.Instance;
				if (instance != null)
				{
					NMerchantInventory inventory = instance.Inventory;
					if (inventory != null && !inventory.IsOpen)
					{
						return (button: instance.MerchantButton, screenContext: (Control)(object)instance);
					}
				}
			}
			if (room is EventRoom eventRoom && eventRoom.CanonicalEvent is FakeMerchant)
			{
				EventModel localMutableEvent = eventRoom.LocalMutableEvent;
				if (localMutableEvent != null && localMutableEvent.Node is NFakeMerchant nFakeMerchant)
				{
					NMerchantInventory inventory = nFakeMerchant.Inventory;
					if (inventory != null && !inventory.IsOpen)
					{
						return (button: nFakeMerchant.MerchantButton, screenContext: (Control)(object)nFakeMerchant);
					}
				}
			}
			return (button: null, screenContext: null);
		}
	}
