		private async Task ReattachMove(IReadOnlyList<Creature> targets)
		{
			SfxCmd.Play("event:/sfx/enemy/enemy_attacks/decimillipede/decimillipede_heal");
			if (base.CombatState.IsLiveCombat())
			{
				await base.Creature.GetPower<ReattachPower>().DoReattach();
			}
			ChangePhobiaModeTexture(ResourceLoader.Load<Texture2D>(PhobiaModeAliveTexture, (string)null, (CacheMode)1));
		}

		private async Task AnimSegmentsAttack()
		{
			if (TestMode.IsOn)
			{
				return;
			}
			IEnumerable<Creature> enumerable = from c in base.CombatState.GetTeammatesOf(base.Creature)
				where c.Monster is DecimillipedeSegment
				select c;
			foreach (Creature item in enumerable)
			{
				((DecimillipedeSegment)item.Monster).SegmentAttack();
			}
			Node2D val = PreloadManager.Cache.GetScene(rocksVfxPath).Instantiate<Node2D>((GenEditState)0);
			((Node)(object)base.Creature.GetVfxContainer())?.AddChildSafely((Node?)(object)val);
			Rect2 viewportRect = ((CanvasItem)NGame.Instance).GetViewportRect();
			val.GlobalPosition = ((Rect2)(ref viewportRect)).Size * 0.5f;
			await Cmd.Wait(0.5f);
		}

		public override Task AfterDeath(PlayerChoiceContext choiceContext, Creature creature, bool wasRemovalPrevented, float deathAnimLength)
		{
			if (creature != base.Creature)
			{
				return Task.CompletedTask;
			}
			if (TestMode.IsOn)
			{
				return Task.CompletedTask;
			}
			ChangePhobiaModeTexture(ResourceLoader.Load<Texture2D>(PhobiaModeDeadTexture, (string)null, (CacheMode)1));
			return Task.CompletedTask;
		}

		private void ChangePhobiaModeTexture(Texture2D tex)
		{
			//IL_0024: Unknown result type (might be due to invalid IL or missing references)
			NCreature creatureNode = base.Creature.GetCreatureNode();
			if (creatureNode != null && creatureNode.Visuals.IsUsingPhobiaModeBody)
			{
				((Sprite2D)creatureNode.Body).Texture = tex;
			}
		}

