		{
			await DamageCmd.Attack(DisintegrateDamage).FromMonster(this).WithAttackerAnim("Attack", 0.6f)
				.WithAttackerFx(null, AttackSfx)
				.WithHitFx("vfx/vfx_attack_slash")
				.Execute(null);
