		private async Task VulnerableSporesMove(IReadOnlyList<Creature> targets)
		{
			if (TestMode.IsOff)
			{
				NCreature creatureNode = base.Creature.GetCreatureNode();
				if (creatureNode != null)
				{
					((Node)creatureNode.Visuals.GetCurrentBody()).GetNode<NFlyconidSporesVfx>(NodePath.op_Implicit("%VfxController"))?.SetSporeTypeIsVulnerable(isVulnerable: true);
				}
			}
			SfxCmd.Play(CastSfx);
			await CreatureCmd.TriggerAnim(base.Creature, "Cast", 0.5f);
