	public sealed class KnowledgeDemon : MonsterModel
	{
		public interface IChoosable
		{
			Task OnChosen();
		}

		private const string _knowledgeDemonCustomTrackName = "knowledge_demon_progress";

		private const string _clapSfx = "event:/sfx/enemy/enemy_attacks/knowledge_demon/knowledge_demon_clap";

		private const string _flameSfx = "event:/sfx/enemy/enemy_attacks/knowledge_demon/knowledge_demon_flame";

		private const string _slapSfx = "event:/sfx/enemy/enemy_attacks/knowledge_demon/knowledge_demon_slap";

		private static readonly LocString _curseOfKnowledgeStartLine = MonsterModel.L10NMonsterLookup("KNOWLEDGE_DEMON.moves.CURSE_OF_KNOWLEDGE.startLine");

		private static readonly LocString _curseOfKnowledgeDoneLine = MonsterModel.L10NMonsterLookup("KNOWLEDGE_DEMON.moves.CURSE_OF_KNOWLEDGE.doneLine");

		private static readonly int[] _disintegrationDamageValues = new int[3] { 6, 7, 8 };

		private static readonly IReadOnlyList<IReadOnlyList<IChoosable>> _curseOfKnowledgeSets = new global::<>z__ReadOnlyArray<IReadOnlyList<IChoosable>>(new IReadOnlyList<IChoosable>[3]
		{
			new global::<>z__ReadOnlyArray<IChoosable>(new IChoosable[2]
			{
				ModelDb.Card<Disintegration>(),
				ModelDb.Card<MindRot>()
			}),
			new global::<>z__ReadOnlyArray<IChoosable>(new IChoosable[2]
			{
				ModelDb.Card<Disintegration>(),
				ModelDb.Card<Sloth>()
			}),
			new global::<>z__ReadOnlyArray<IChoosable>(new IChoosable[2]
			{
				ModelDb.Card<Disintegration>(),
				ModelDb.Card<WasteAway>()
			})
		});

		private int _curseOfKnowledgeCounter;

		private const int _knowledgeOverwhelmingRepeat = 3;

		private const int _ponderHeal = 30;

		private bool _isBurnt;

		private const string _mindRotTrigger = "MindRotTrigger";

		private const string _lightAttackTrigger = "LightAttackTrigger";

		private const string _mediumAttackTrigger = "MediumAttackTrigger";

		private const string _heavyAttackTrigger = "HeavyAttackTrigger";

		private const string _healTrigger = "HealTrigger";

		private int CurseOfKnowledgeCounter
		{
			get
			{
				return _curseOfKnowledgeCounter;
			}
			set
			{
				AssertMutable();
				_curseOfKnowledgeCounter = value;
			}
		}

		public override int MinInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 399, 379);

		public override int MaxInitialHp => MinInitialHp;

		private int SlapDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 18, 17);

		private int PonderDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 13, 11);

		private int KnowledgeOverwhelmingDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 9, 8);

		private int PonderStrength => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 3, 2);

		public bool IsBurnt
		{
			get
			{
				return _isBurnt;
			}
			set
			{
				AssertMutable();
				_isBurnt = value;
			}
		}

		public override void BeforeRemovedFromRoom()
		{
			NRunMusicController.Instance?.UpdateMusicParameter("knowledge_demon_progress", 5f);
		}

		protected override MonsterMoveStateMachine GenerateMoveStateMachine()
		{
			List<MonsterState> list = new List<MonsterState>();
			MoveState moveState = new MoveState("CURSE_OF_KNOWLEDGE_MOVE", CurseOfKnowledgeMove, new DebuffIntent());
			MoveState moveState2 = new MoveState("SLAP_MOVE", SlapMove, new SingleAttackIntent(SlapDamage));
			MoveState moveState3 = new MoveState("KNOWLEDGE_OVERWHELMING_MOVE", KnowledgeOverwhelmingMove, new MultiAttackIntent(KnowledgeOverwhelmingDamage, 3));
			MoveState moveState4 = new MoveState("PONDER_MOVE", PonderMove, new SingleAttackIntent(PonderDamage), new HealIntent(), new BuffIntent());
			ConditionalBranchState conditionalBranchState = new ConditionalBranchState("CurseOfKnowledgeBranch");
			moveState.FollowUpState = moveState2;
			moveState2.FollowUpState = moveState3;
			moveState3.FollowUpState = moveState4;
			moveState4.FollowUpState = conditionalBranchState;
			conditionalBranchState.AddState(moveState, () => _curseOfKnowledgeCounter < 3);
			conditionalBranchState.AddState(moveState2, () => _curseOfKnowledgeCounter >= 3);
			list.Add(conditionalBranchState);
			list.Add(moveState);
			list.Add(moveState2);
			list.Add(moveState4);
			list.Add(moveState3);
			return new MonsterMoveStateMachine(list, moveState);
		}

		private async Task CurseOfKnowledgeMove(IReadOnlyList<Creature> targets)
		{
			if (CurseOfKnowledgeCounter >= _curseOfKnowledgeSets.Count)
			{
				throw new InvalidOperationException($"There are no valid sets at this index {CurseOfKnowledgeCounter}");
			}
			TalkCmd.Play(_curseOfKnowledgeStartLine, base.Creature, VfxColor.Gold, VfxDuration.Standard);
			await CreatureCmd.TriggerAnim(base.Creature, "MindRotTrigger", 1f);
			List<Task> list = new List<Task>();
			foreach (Creature target in targets)
			{
				list.Add(ChooseCurse(target));
			}
			await Task.WhenAll(list);
			TalkCmd.Play(_curseOfKnowledgeDoneLine, base.Creature, VfxColor.Gold, VfxDuration.Standard);
			if (base.CombatState.IsLiveCombat())
			{
				CurseOfKnowledgeCounter++;
			}
		}

		private async Task ChooseCurse(Creature target)
		{
			if (target.IsDead)
			{
				return;
			}
			int disintegrationDamage = _disintegrationDamageValues[CurseOfKnowledgeCounter];
			List<CardModel> cards = _curseOfKnowledgeSets[CurseOfKnowledgeCounter].Select(delegate(IChoosable c)
			{
				CardModel cardModel2 = base.CombatState.CreateCard((CardModel)c, target.Player);
				if (cardModel2 is Disintegration)
				{
					cardModel2.DynamicVars["DisintegrationPower"].BaseValue = disintegrationDamage;
				}
				return cardModel2;
			}).ToList();
			CardModel cardModel = await CardSelectCmd.FromChooseACardScreen(new BlockingPlayerChoiceContext(), cards, target.Player);
			if (cardModel != null)
			{
				await ((IChoosable)cardModel).OnChosen();
			}
		}

		private async Task SlapMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(SlapDamage).FromMonster(this).WithAttackerAnim("MediumAttackTrigger", 0.5f)
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/knowledge_demon/knowledge_demon_slap")
				.WithHitFx("vfx/vfx_attack_blunt", null, "blunt_attack.mp3")
				.Execute(null);
		}

		private async Task KnowledgeOverwhelmingMove(IReadOnlyList<Creature> targets)
		{
			IsBurnt = true;
			NRunMusicController.Instance?.UpdateMusicParameter("knowledge_demon_progress", 1f);
			await DamageCmd.Attack(KnowledgeOverwhelmingDamage).WithHitCount(3).FromMonster(this)
				.WithAttackerAnim("HeavyAttackTrigger", 0.85f)
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/knowledge_demon/knowledge_demon_clap")
				.OnlyPlayAnimOnce()
				.WithHitFx("vfx/vfx_attack_blunt", null, "blunt_attack.mp3")
				.Execute(null);
		}

		private async Task PonderMove(IReadOnlyList<Creature> targets)
		{
			await CreatureCmd.TriggerAnim(base.Creature, "HealTrigger", 1.8f);
			NRunMusicController.Instance?.UpdateMusicParameter("knowledge_demon_progress", 2f);
			IsBurnt = false;
			await DamageCmd.Attack(PonderDamage).FromMonster(this).WithHitFx("vfx/vfx_attack_blunt", null, "blunt_attack.mp3")
				.Execute(null);
			await CreatureCmd.Heal(base.Creature, 30 * base.CombatState.Players.Count);
			await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), base.Creature, PonderStrength, base.Creature, null);
		}

		public override CreatureAnimator GenerateAnimator(MegaSprite controller)
		{
			AnimState animState = new AnimState("idle_loop", isLooping: true);
			AnimState animState2 = new AnimState("attack_light");
			AnimState animState3 = new AnimState("attack_medium");
			AnimState animState4 = new AnimState("attack_heavy");
			AnimState animState5 = new AnimState("brain_rot");
			AnimState animState6 = new AnimState("heal");
			AnimState nextState = new AnimState("burnt_loop", isLooping: true);
			AnimState animState7 = new AnimState("hurt");
			AnimState state = new AnimState("die");
			AnimState animState8 = new AnimState("hurt_burnt");
			AnimState state2 = new AnimState("die_burnt");
			animState2.NextState = animState;
			animState3.NextState = animState;
			animState4.NextState = nextState;
			animState5.NextState = animState;
			animState6.NextState = animState;
			animState7.NextState = animState;
			animState8.NextState = nextState;
			CreatureAnimator creatureAnimator = new CreatureAnimator(animState, controller);
			creatureAnimator.AddAnyState("LightAttackTrigger", animState2);
			creatureAnimator.AddAnyState("MediumAttackTrigger", animState3);
			creatureAnimator.AddAnyState("HeavyAttackTrigger", animState4);
			creatureAnimator.AddAnyState("MindRotTrigger", animState5);
			creatureAnimator.AddAnyState("HealTrigger", animState6);
			creatureAnimator.AddAnyState("Dead", state, () => !_isBurnt);
			creatureAnimator.AddAnyState("Hit", animState7, () => !_isBurnt);
			creatureAnimator.AddAnyState("Dead", state2, () => _isBurnt);
			creatureAnimator.AddAnyState("Hit", animState8, () => _isBurnt);
			return creatureAnimator;
		}
	}
	public sealed class LagavulinMatriarch : MonsterModel
	{
		private const string _sleepMoveId = "SLEEP_MOVE";

		public const string slashMoveId = "SLASH_MOVE";

		private const string _sleepTrigger = "Sleep";

		public const string wakeTrigger = "Wake";

		private const string _attackHeavyTrigger = "AttackHeavy";

		private const string _attackDoubleTrigger = "AttackDouble";

		private const string _slamSfx = "event:/sfx/enemy/enemy_attacks/lagavulin_matriarch/lagavulin_matriarch_slam";

		private const string _castSfx = "event:/sfx/enemy/enemy_attacks/lagavulin_matriarch/lagavulin_matriarch_cast";

		public const string awakenSfx = "event:/sfx/enemy/enemy_attacks/lagavulin_matriarch/lagavulin_matriarch_awaken";

		private const string _attackStabSfx = "event:/sfx/enemy/enemy_attacks/lagavulin_matriarch/lagavulin_matriarch_attack_stab";

		private bool _isAwake;

		private bool _isShellAwake;

		private NSleepingVfx? _sleepingVfx;

		public override int MinInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 233, 222);

		public override int MaxInitialHp => MinInitialHp;

		private int SlashDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 21, 19);

		private int Slash2Damage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 14, 12);

		private int Slash2Block => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 14, 12);

		private int DisembowelDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 10, 9);

		private int DisembowelRepeat => 2;

		public override DamageSfxType TakeDamageSfxType => DamageSfxType.ArmorBig;

		public bool IsAwake
		{
			get
			{
				return _isAwake;
			}
			set
			{
				AssertMutable();
				_isAwake = value;
			}
		}

		public bool IsShellAwake
		{
			get
			{
				return _isShellAwake;
			}
			set
			{
				AssertMutable();
				_isShellAwake = value;
			}
		}

		private NSleepingVfx? SleepingVfx
		{
			get
			{
				return _sleepingVfx;
			}
			set
			{
				AssertMutable();
				_sleepingVfx = value;
			}
		}

		public override void SetupSkins(MegaSprite spine, MegaSkeleton skeleton)
		{
			spine.GetAnimationState().SetAnimation("_tracks/eyes_closed_loop", loop: true, 1);
		}

		public override async Task AfterAddedToRoom()
		{
			await base.AfterAddedToRoom();
			await Sleep();
		}

		private async Task Sleep()
		{
			IsAwake = false;
			await CreatureCmd.TriggerAnim(base.Creature, "Sleep", 0f);
			await PowerCmd.Apply<PlatingPower>(new ThrowingPlayerChoiceContext(), base.Creature, 12m, base.Creature, null);
			await PowerCmd.Apply<AsleepPower>(new ThrowingPlayerChoiceContext(), base.Creature, 3m, base.Creature, null);
			Marker2D val = base.Creature.GetCreatureNode()?.GetSpecialNode<Marker2D>("%SleepVfxPos");
			if (val != null)
			{
				SleepingVfx = NSleepingVfx.Create(((Node2D)val).GlobalPosition);
				((Node)(object)val).AddChildSafely((Node?)(object)SleepingVfx);
				((Node2D)SleepingVfx).Position = Vector2.Zero;
			}
		}

		public override Task AfterDamageReceived(PlayerChoiceContext choiceContext, Creature target, DamageResult result, ValueProp props, Creature? dealer, CardModel? cardSource)
		{
			if (target != base.Creature)
			{
				return Task.CompletedTask;
			}
			SleepingVfx?.Stop();
			SleepingVfx = null;
			if (base.Creature.CurrentHp <= base.Creature.MaxHp / 2 && !IsShellAwake)
			{
				NCreature creatureNode = base.Creature.GetCreatureNode();
				creatureNode?.SpineAnimation.SetAnimation("_tracks/eyes_open", loop: false, 1);
				creatureNode?.SpineAnimation.AddAnimation("_tracks/eyes_open_loop", 0f, loop: true, 1);
				IsShellAwake = true;
			}
			return Task.CompletedTask;
		}

		public override Task AfterDeath(PlayerChoiceContext choiceContext, Creature creature, bool wasRemovalPrevented, float deathAnimLength)
		{
			if (creature != base.Creature)
			{
				return Task.CompletedTask;
			}
			base.Creature.GetCreatureNode()?.SpineAnimation.SetAnimation("_tracks/eyes_dead", loop: false, 1);
			SleepingVfx?.Stop();
			SleepingVfx = null;
			return Task.CompletedTask;
		}

		protected override MonsterMoveStateMachine GenerateMoveStateMachine()
		{
			List<MonsterState> list = new List<MonsterState>();
			MoveState moveState = new MoveState("SLEEP_MOVE", SleepMove, new SleepIntent());
			MoveState moveState2 = new MoveState("SLASH_MOVE", SlashMove, new SingleAttackIntent(SlashDamage));
			MoveState moveState3 = new MoveState("SLASH2_MOVE", Slash2Move, new SingleAttackIntent(Slash2Damage), new DefendIntent());
			MoveState moveState4 = new MoveState("DISEMBOWEL_MOVE", DisembowelMove, new MultiAttackIntent(DisembowelDamage, DisembowelRepeat));
			MoveState moveState5 = new MoveState("SOUL_SIPHON_MOVE", SoulSiphonMove, new DebuffIntent(), new BuffIntent());
			ConditionalBranchState conditionalBranchState = (ConditionalBranchState)(moveState.FollowUpState = new ConditionalBranchState("SLEEP_BRANCH"));
			moveState2.FollowUpState = moveState4;
			moveState4.FollowUpState = moveState3;
			moveState3.FollowUpState = moveState5;
			moveState5.FollowUpState = moveState2;
			conditionalBranchState.AddState(moveState, () => base.Creature.HasPower<AsleepPower>());
			conditionalBranchState.AddState(moveState2, () => !base.Creature.HasPower<AsleepPower>());
			list.Add(conditionalBranchState);
			list.Add(moveState);
			list.Add(moveState2);
			list.Add(moveState3);
			list.Add(moveState5);
			list.Add(moveState4);
			return new MonsterMoveStateMachine(list, moveState);
		}

		private Task SleepMove(IReadOnlyList<Creature> targets)
		{
			return Task.CompletedTask;
		}

		public async Task WakeUpMove(IReadOnlyList<Creature> _)
		{
			if (!_isAwake)
			{
				SfxCmd.Play("event:/sfx/enemy/enemy_attacks/lagavulin_matriarch/lagavulin_matriarch_awaken");
				await CreatureCmd.TriggerAnim(base.Creature, "Wake", 0.6f);
				SleepingVfx?.Stop();
				SleepingVfx = null;
				IsAwake = true;
			}
		}

		private async Task SlashMove(IReadOnlyList<Creature> targets)
		{
			SleepingVfx?.Stop();
			SleepingVfx = null;
			await DamageCmd.Attack(SlashDamage).FromMonster(this).WithAttackerAnim("AttackHeavy", 0.3f)
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/lagavulin_matriarch/lagavulin_matriarch_slam")
				.WithHitFx("vfx/vfx_attack_slash")
				.Execute(null);
		}

		private async Task Slash2Move(IReadOnlyList<Creature> targets)
		{
			SleepingVfx?.Stop();
			SleepingVfx = null;
			await DamageCmd.Attack(Slash2Damage).FromMonster(this).WithAttackerAnim("AttackHeavy", 0.2f)
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/lagavulin_matriarch/lagavulin_matriarch_slam")
				.WithHitFx("vfx/vfx_attack_slash")
				.Execute(null);
			await CreatureCmd.GainBlock(base.Creature, Slash2Block, ValueProp.Move, null);
		}

		private async Task DisembowelMove(IReadOnlyList<Creature> targets)
		{
			SleepingVfx?.Stop();
			SleepingVfx = null;
			await DamageCmd.Attack(DisembowelDamage).WithHitCount(DisembowelRepeat).FromMonster(this)
				.WithAttackerAnim("AttackDouble", 0.15f)
				.OnlyPlayAnimOnce()
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/lagavulin_matriarch/lagavulin_matriarch_attack_stab")
				.WithHitFx("vfx/vfx_attack_slash")
				.Execute(null);
		}

		private async Task SoulSiphonMove(IReadOnlyList<Creature> targets)
		{
			SleepingVfx?.Stop();
			SleepingVfx = null;
			SfxCmd.Play("event:/sfx/enemy/enemy_attacks/lagavulin_matriarch/lagavulin_matriarch_cast");
			await CreatureCmd.TriggerAnim(base.Creature, "Cast", 0.6f);
			await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), targets, -2m, base.Creature, null);
			await PowerCmd.Apply<DexterityPower>(new ThrowingPlayerChoiceContext(), targets, -2m, base.Creature, null);
			await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), base.Creature, 2m, base.Creature, null);
		}

		public override CreatureAnimator GenerateAnimator(MegaSprite controller)
		{
			AnimState state = new AnimState("sleep_loop", isLooping: true);
			AnimState animState = new AnimState("hurt_sleeping");
			AnimState animState2 = new AnimState("wake_up");
			AnimState animState3 = new AnimState("idle_loop", isLooping: true);
			AnimState animState4 = new AnimState("cast");
			AnimState animState5 = new AnimState("attack_heavy");
			AnimState animState6 = new AnimState("attack_double");
			AnimState animState7 = new AnimState("hurt");
			AnimState state2 = new AnimState("die");
			animState.NextState = animState2;
			animState2.NextState = animState3;
			animState4.NextState = animState3;
			animState5.NextState = animState3;
			animState6.NextState = animState3;
			animState7.NextState = animState3;
			CreatureAnimator creatureAnimator = new CreatureAnimator(animState3, controller);
			creatureAnimator.AddAnyState("Sleep", state);
			creatureAnimator.AddAnyState("Wake", animState2, () => !IsAwake);
			creatureAnimator.AddAnyState("Cast", animState4);
			creatureAnimator.AddAnyState("AttackHeavy", animState5);
			creatureAnimator.AddAnyState("AttackDouble", animState6);
			creatureAnimator.AddAnyState("Dead", state2);
			creatureAnimator.AddAnyState("Hit", animState7, () => IsAwake);
			creatureAnimator.AddAnyState("Hit", animState, () => !IsAwake);
			return creatureAnimator;
		}

		protected override bool ShouldShowMoveInBestiary(string moveStateId)
		{
			return moveStateId != "SLEEP_MOVE";
		}

		public override List<BestiaryMonsterMove> GenerateBestiaryMoveList(NCreatureVisuals? creatureVisuals)
		{
			List<BestiaryMonsterMove> list = base.GenerateBestiaryMoveList(creatureVisuals);
			list.Insert(0, BestiaryMonsterMove.FromAction(GetBestiaryMoveName("SLEEP"), Sleep));
			list.Insert(1, BestiaryMonsterMove.FromNonStateMove(GetBestiaryMoveName("WAKE_UP"), WakeUpMove));
			return list;
		}
	}
	public sealed class LeafSlimeM : MonsterModel
	{
		private const int _stickyAmount = 2;

		public override int MinInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 33, 32);

		public override int MaxInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 36, 35);

		private int ClumpDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 9, 8);

		public override DamageSfxType TakeDamageSfxType => DamageSfxType.Slime;

		protected override MonsterMoveStateMachine GenerateMoveStateMachine()
		{
			List<MonsterState> list = new List<MonsterState>();
			MoveState moveState = new MoveState("CLUMP_SHOT", ClumpShotMove, new SingleAttackIntent(ClumpDamage));
			MoveState moveState2 = (MoveState)(moveState.FollowUpState = new MoveState("STICKY_SHOT", StickyShotMove, new StatusIntent(2))
			{
				FollowUpState = moveState
			});
			list.Add(moveState);
			list.Add(moveState2);
			return new MonsterMoveStateMachine(list, moveState2);
		}

		private async Task ClumpShotMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(ClumpDamage).FromMonster(this).WithAttackerAnim("Attack", 0.15f)
				.WithAttackerFx(null, AttackSfx)
				.WithHitFx("vfx/vfx_slime_impact")
				.Execute(null);
		}

		private async Task StickyShotMove(IReadOnlyList<Creature> targets)
		{
			if (TestMode.IsOff)
			{
				NCreature nCreature = null;
				foreach (Creature target in targets)
				{
					NCreature creatureNode = target.GetCreatureNode();
					if (creatureNode != null && (nCreature == null || ((Control)nCreature).GlobalPosition.X > ((Control)creatureNode).GlobalPosition.X))
					{
						nCreature = creatureNode;
					}
				}
				NCreature creatureNode2 = base.Creature.GetCreatureNode();
				Node2D val = creatureNode2?.GetSpecialNode<Node2D>("Visuals/SpitTarget");
				if (creatureNode2 != null && val != null && nCreature != null)
				{
					val.GlobalPosition = new Vector2(((Control)nCreature).GlobalPosition.X, val.GlobalPosition.Y);
				}
			}
			SfxCmd.Play(CastSfx);
			await CreatureCmd.TriggerAnim(base.Creature, "Cast", 1f);
			VfxCmd.PlayOnCreatureCenters(targets, "vfx/vfx_slime_impact");
			await CardPileCmd.AddToCombatAndPreview<Slimed>(targets, PileType.Discard, 2, null);
		}
	}
