			await CreatureCmd.TriggerAnim(base.Creature, "buffTrigger", 1f);
			await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), base.Creature, NutritionalPasteStrengthAmount, base.Creature, null);
		}

