	public sealed class PhantasmalGardener : MonsterModel
	{
		private int _enlargeTriggers;

		private const string _attackMultiTrigger = "AttackMulti";

		public const string blockStartTrigger = "BlockStart";

		public const string blockEndTrigger = "BlockEnd";

		private const string _biteSfx = "event:/sfx/enemy/enemy_attacks/phantasmal_gardeners/phantasmal_gardeners_attack_bite";

		private const string _lickSfx = "event:/sfx/enemy/enemy_attacks/phantasmal_gardeners/phantasmal_gardeners_attack_lick";

		private const string _buffSfx = "event:/sfx/enemy/enemy_attacks/phantasmal_gardeners/phantasmal_gardeners_buff";

		public override int MinInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 27, 26);

		public override int MaxInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 32, 31);

		private int BiteDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 5, 5);

		private int LashDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 7, 7);

		private int FlailDamage => 1;

		private int FlailRepeat => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 3, 3);

		private int EnlargeStr => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 3, 2);

		private int SkittishAmount => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 7, 6);

		public int EnlargeTriggers
		{
			get
			{
				return _enlargeTriggers;
			}
			set
			{
				AssertMutable();
				_enlargeTriggers = value;
			}
		}

		public override bool ShouldFadeAfterDeath => false;

		public float CurrentScale { get; private set; } = 1f;

		public override DamageSfxType TakeDamageSfxType => DamageSfxType.Magic;

		public override string DeathSfx => "event:/sfx/enemy/enemy_attacks/phantasmal_gardeners/phantasmal_gardeners_die";

		public override void SetupSkins(MegaSprite spine, MegaSkeleton skeleton)
		{
			MegaSkin megaSkin = spine.NewSkin("custom-skin");
			MegaSkeletonDataResource data = skeleton.GetData();
			string slotName = base.Creature.SlotName;
			if ((slotName == "first" || slotName == "third") ? true : false)
			{
				megaSkin.AddSkin(data.FindSkin("tall"));
			}
			else
			{
				megaSkin.AddSkin(data.FindSkin("short"));
			}
			skeleton.SetSkin(megaSkin);
			skeleton.SetSlotsToSetupPose();
		}

		public override async Task AfterAddedToRoom()
		{
			await base.AfterAddedToRoom();
			await PowerCmd.Apply<SkittishPower>(new ThrowingPlayerChoiceContext(), base.Creature, SkittishAmount, base.Creature, null);
		}

		protected override MonsterMoveStateMachine GenerateMoveStateMachine()
		{
			List<MonsterState> list = new List<MonsterState>();
			MoveState moveState = new MoveState("BITE_MOVE", BiteMove, new SingleAttackIntent(BiteDamage));
			MoveState moveState2 = new MoveState("LASH_MOVE", LashMove, new SingleAttackIntent(LashDamage));
			MoveState moveState3 = new MoveState("FLAIL_MOVE", FlailMove, new MultiAttackIntent(FlailDamage, FlailRepeat));
			MoveState moveState4 = new MoveState("ENLARGE_MOVE", EnlargeMove, new BuffIntent());
			ConditionalBranchState conditionalBranchState = new ConditionalBranchState("INIT_MOVE");
			conditionalBranchState.AddState(moveState3, () => base.Creature.SlotName == "first");
			conditionalBranchState.AddState(moveState, () => base.Creature.SlotName == "second");
			conditionalBranchState.AddState(moveState2, () => base.Creature.SlotName == "third");
			conditionalBranchState.AddState(moveState4, () => base.Creature.SlotName == "fourth");
			moveState.FollowUpState = moveState2;
			moveState2.FollowUpState = moveState3;
			moveState3.FollowUpState = moveState4;
			moveState4.FollowUpState = moveState;
			list.Add(moveState);
			list.Add(moveState2);
			list.Add(moveState4);
			list.Add(moveState3);
			return new MonsterMoveStateMachine(list, conditionalBranchState);
		}

		private async Task BiteMove(IReadOnlyList<Creature> targets)
		{
			NCombatRoom.Instance?.GetCreatureNode(base.Creature)?.SetDefaultScaleTo(CurrentScale, 0.75f);
			await DamageCmd.Attack(BiteDamage).FromMonster(this).WithAttackerAnim("Attack", 0.3f)
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/phantasmal_gardeners/phantasmal_gardeners_attack_bite")
				.WithHitFx("vfx/vfx_bite")
				.Execute(null);
		}

		private async Task LashMove(IReadOnlyList<Creature> targets)
		{
			NCombatRoom.Instance?.GetCreatureNode(base.Creature)?.SetDefaultScaleTo(CurrentScale, 0.75f);
			await DamageCmd.Attack(LashDamage).FromMonster(this).WithAttackerAnim("Attack", 0.3f)
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/phantasmal_gardeners/phantasmal_gardeners_attack_bite")
				.WithHitFx("vfx/vfx_bite")
				.Execute(null);
		}

		private async Task FlailMove(IReadOnlyList<Creature> targets)
		{
			NCombatRoom.Instance?.GetCreatureNode(base.Creature)?.SetDefaultScaleTo(CurrentScale, 0.35f);
			await DamageCmd.Attack(FlailDamage).WithHitCount(FlailRepeat).OnlyPlayAnimOnce()
				.FromMonster(this)
				.WithAttackerAnim("AttackMulti", 0.3f)
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/phantasmal_gardeners/phantasmal_gardeners_attack_lick")
				.WithHitFx("vfx/vfx_attack_blunt")
				.Execute(null);
		}

		private async Task EnlargeMove(IReadOnlyList<Creature> targets)
		{
			SfxCmd.Play("event:/sfx/enemy/enemy_attacks/phantasmal_gardeners/phantasmal_gardeners_buff");
			await CreatureCmd.TriggerAnim(base.Creature, "Cast", 1.5f);
			await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), base.Creature, EnlargeStr, base.Creature, null);
			EnlargeTriggers++;
			CurrentScale = 1f + 0.1f * Mathf.Log((float)EnlargeTriggers + 1f);
			NCombatRoom.Instance?.GetCreatureNode(base.Creature)?.SetDefaultScaleTo(CurrentScale, 0.75f);
		}

		public override CreatureAnimator GenerateAnimator(MegaSprite controller)
		{
			AnimState animState = new AnimState("idle_loop", isLooping: true);
			AnimState animState2 = new AnimState("buff");
			AnimState animState3 = new AnimState("attack");
			AnimState animState4 = new AnimState("attack_multi");
			AnimState animState5 = new AnimState("hurt_extended");
			AnimState animState6 = new AnimState("hurt");
			AnimState state = new AnimState("die");
			AnimState nextState = new AnimState("block_loop", isLooping: true);
			AnimState animState7 = new AnimState("block_start");
			AnimState animState8 = new AnimState("block_end");
			animState2.NextState = animState;
			animState3.NextState = animState;
			animState4.NextState = animState;
			animState5.NextState = animState;
			animState6.NextState = nextState;
			animState7.NextState = nextState;
			animState8.NextState = animState;
			CreatureAnimator creatureAnimator = new CreatureAnimator(animState, controller);
			creatureAnimator.AddAnyState("Idle", animState);
			creatureAnimator.AddAnyState("Cast", animState2);
			creatureAnimator.AddAnyState("Attack", animState3);
			creatureAnimator.AddAnyState("AttackMulti", animState4);
			creatureAnimator.AddAnyState("Dead", state);
			creatureAnimator.AddAnyState("Hit", animState5, () => !base.Creature.GetPower<SkittishPower>().HasGainedBlockThisTurn);
			creatureAnimator.AddAnyState("Hit", animState6, () => base.Creature.GetPower<SkittishPower>().HasGainedBlockThisTurn);
			creatureAnimator.AddAnyState("BlockStart", animState7);
			creatureAnimator.AddAnyState("BlockEnd", animState8);
			return creatureAnimator;
		}

		public override List<BestiaryMonsterMove> GenerateBestiaryMoveList(NCreatureVisuals? creatureVisuals)
		{
			List<BestiaryMonsterMove> list = base.GenerateBestiaryMoveList(creatureVisuals);
			list.RemoveAll((BestiaryMonsterMove m) => m.stateId == "LASH_MOVE");
			return list;
		}
	}
	public sealed class PhrogParasite : MonsterModel
	{
		private const int _lashRepeat = 4;

		private const int _infestAmt = 3;

		public override int MinInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 66, 61);

		public override int MaxInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 68, 64);

		private int LashDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 5, 4);

		public override DamageSfxType TakeDamageSfxType => DamageSfxType.Plant;

		public override async Task AfterAddedToRoom()
		{
			await base.AfterAddedToRoom();
			await PowerCmd.Apply<InfestedPower>(new ThrowingPlayerChoiceContext(), base.Creature, 4m, base.Creature, null);
		}

		protected override MonsterMoveStateMachine GenerateMoveStateMachine()
		{
			List<MonsterState> list = new List<MonsterState>();
			MoveState moveState = new MoveState("INFECT_MOVE", InfectMove, new StatusIntent(3));
			MoveState moveState2 = new MoveState("LASH_MOVE", LashMove, new MultiAttackIntent(LashDamage, 4));
			RandomBranchState randomBranchState = new RandomBranchState("RAND");
			moveState.FollowUpState = moveState2;
			moveState2.FollowUpState = moveState;
			randomBranchState.AddBranch(moveState, MoveRepeatType.CannotRepeat);
			randomBranchState.AddBranch(moveState2, MoveRepeatType.CannotRepeat);
			list.Add(moveState);
			list.Add(moveState2);
			list.Add(randomBranchState);
			return new MonsterMoveStateMachine(list, moveState);
		}

		private async Task LashMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(LashDamage).WithHitCount(4).FromMonster(this)
				.WithAttackerAnim("Attack", 0.55f)
				.OnlyPlayAnimOnce()
				.WithAttackerFx(null, AttackSfx)
				.WithHitVfxNode(NWormyImpactVfx.Create)
				.Execute(null);
		}

		private async Task InfectMove(IReadOnlyList<Creature> targets)
		{
			SfxCmd.Play(CastSfx);
			await CreatureCmd.TriggerAnim(base.Creature, "Cast", 0.75f);
			foreach (Creature target in targets)
			{
				NWormyImpactVfx nWormyImpactVfx = NWormyImpactVfx.Create(target);
				if (nWormyImpactVfx != null)
				{
					((Node)(object)target.GetVfxContainer())?.AddChildSafely((Node?)(object)nWormyImpactVfx);
				}
			}
			await CardPileCmd.AddToCombatAndPreview<Infection>(targets, PileType.Discard, 3, null);
		}
	}
	public sealed class PunchConstruct : MonsterModel
	{
		private const string _attackDoubleTrigger = "DoubleAttack";

		private bool _startsWithFastPunch;

		private int _startingHpReduction;

		private const string _attackSingleSfx = "event:/sfx/enemy/enemy_attacks/punch_construct/punch_construct_attack_single";

		private const string _attackDoubleSfx = "event:/sfx/enemy/enemy_attacks/punch_construct/punch_construct_attack_double";

		private const string _buffSfx = "event:/sfx/enemy/enemy_attacks/punch_construct/punch_construct_buff";

		public override int MinInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 60, 55);

		public override int MaxInitialHp => MinInitialHp;

		private int StrongPunchDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 16, 14);

		private int FastPunchDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 6, 5);

		private int FastPunchRepeat => 2;

		public override DamageSfxType TakeDamageSfxType => DamageSfxType.Armor;

		public bool StartsWithFastPunch
		{
			get
			{
				return _startsWithFastPunch;
			}
			set
			{
				AssertMutable();
				_startsWithFastPunch = value;
			}
		}

		public int StartingHpReduction
		{
			get
			{
				return _startingHpReduction;
			}
			set
			{
				AssertMutable();
				_startingHpReduction = value;
			}
		}

		public override async Task AfterAddedToRoom()
		{
			await base.AfterAddedToRoom();
			await PowerCmd.Apply<ArtifactPower>(new ThrowingPlayerChoiceContext(), base.Creature, 1m, base.Creature, null);
			if (StartingHpReduction > 0)
			{
				base.Creature.SetCurrentHpInternal(Math.Max(1, base.Creature.CurrentHp - StartingHpReduction));
			}
		}

		protected override MonsterMoveStateMachine GenerateMoveStateMachine()
		{
			List<MonsterState> list = new List<MonsterState>();
			MoveState moveState = new MoveState("READY_MOVE", ReadyMove, new DefendIntent());
			MoveState moveState2 = new MoveState("STRONG_PUNCH_MOVE", StrongPunchMove, new SingleAttackIntent(StrongPunchDamage));
			MoveState moveState3 = (MoveState)(moveState.FollowUpState = new MoveState("FAST_PUNCH_MOVE", FastPunchMove, new MultiAttackIntent(FastPunchDamage, FastPunchRepeat), new DebuffIntent()));
			moveState3.FollowUpState = moveState2;
			moveState2.FollowUpState = moveState;
			list.Add(moveState);
			list.Add(moveState3);
			list.Add(moveState2);
			return new MonsterMoveStateMachine(list, StartsWithFastPunch ? moveState3 : moveState);
		}

		private async Task ReadyMove(IReadOnlyList<Creature> targets)
		{
			SfxCmd.Play("event:/sfx/enemy/enemy_attacks/punch_construct/punch_construct_buff");
			await CreatureCmd.TriggerAnim(base.Creature, "Cast", 0.8f);
			await CreatureCmd.GainBlock(base.Creature, 10m, ValueProp.Move, null);
		}

		private async Task StrongPunchMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(StrongPunchDamage).FromMonster(this).WithAttackerAnim("Attack", 0.25f)
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/punch_construct/punch_construct_attack_single")
				.WithHitFx("vfx/vfx_attack_blunt")
				.Execute(null);
		}

		private async Task FastPunchMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(FastPunchDamage).WithHitCount(FastPunchRepeat).FromMonster(this)
				.WithAttackerAnim("DoubleAttack", 0.2f)
				.OnlyPlayAnimOnce()
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/punch_construct/punch_construct_attack_double")
				.WithHitFx("vfx/vfx_attack_blunt")
				.Execute(null);
			await PowerCmd.Apply<FrailPower>(new ThrowingPlayerChoiceContext(), targets, 1m, base.Creature, null);
		}

		public override CreatureAnimator GenerateAnimator(MegaSprite controller)
		{
			AnimState animState = new AnimState("idle_loop", isLooping: true);
			AnimState animState2 = new AnimState("attack_double");
			AnimState animState3 = new AnimState("block");
			AnimState animState4 = new AnimState("attack");
			AnimState animState5 = new AnimState("hurt");
			AnimState state = new AnimState("die");
			animState3.NextState = animState;
			animState4.NextState = animState;
			animState5.NextState = animState;
			animState2.NextState = animState;
			CreatureAnimator creatureAnimator = new CreatureAnimator(animState, controller);
			creatureAnimator.AddAnyState("Cast", animState3);
			creatureAnimator.AddAnyState("Attack", animState4);
			creatureAnimator.AddAnyState("Dead", state);
			creatureAnimator.AddAnyState("Hit", animState5);
			creatureAnimator.AddAnyState("DoubleAttack", animState2);
			return creatureAnimator;
		}
	}
	public sealed class Queen : MonsterModel
	{
		private const string _puppetStringsMove = "PUPPET_STRINGS_MOVE";

		private const string _burnBrightForMeMove = "BURN_BRIGHT_FOR_ME_MOVE";

		private const string _executionMove = "EXECUTION_MOVE";

		private const string _enrageMove = "ENRAGE_MOVE";

		private const string _queenTrackName = "queen_progress";

		private const string _castSfx = "event:/sfx/enemy/enemy_attacks/queen/queen_cast";

		private const int _offWithYourHeadRepeat = 5;

		private bool _hasAmalgamDied;

		private Creature? _amalgam;

		private MoveState _burnBrightForMeState;

		private MoveState _enragedState;

		protected override string AttackSfx => "event:/sfx/enemy/enemy_attacks/queen/queen_arms_attack";

		public override IEnumerable<string> AssetPaths => base.AssetPaths.Concat(ModelDb.Monster<TorchHeadAmalgam>().AssetPaths);

		public override int MinInitialHp => AscensionHelper.GetValueIfAscension(AscensionLevel.ToughEnemies, 419, 400);

		public override int MaxInitialHp => MinInitialHp;

		public override DamageSfxType TakeDamageSfxType => DamageSfxType.Armor;

		private int OffWithYourHeadDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 4, 3);

		private int ExecutionDamage => AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 18, 15);

		private bool HasAmalgamDied
		{
			get
			{
				return _hasAmalgamDied;
			}
			set
			{
				AssertMutable();
				_hasAmalgamDied = value;
			}
		}

		private Creature? Amalgam
		{
			get
			{
				return _amalgam;
			}
			set
			{
				AssertMutable();
				_amalgam = value;
			}
		}

		private MoveState BurnBrightForMeState
		{
			get
			{
				return _burnBrightForMeState;
			}
			set
			{
				AssertMutable();
				_burnBrightForMeState = value;
			}
		}

		private MoveState EnragedState
		{
			get
			{
				return _enragedState;
			}
			set
			{
				AssertMutable();
				_enragedState = value;
			}
		}

		public override void SetupSkins(MegaSprite spine, MegaSkeleton skeleton)
		{
			spine.GetAnimationState().SetAnimation("tracks/writhe", loop: true, 1);
		}

		public override void BeforeRemovedFromRoom()
		{
			if (!base.CombatState.RunState.IsGameOver)
			{
				NCombatRoom.Instance?.GetCreatureNode(base.Creature)?.SpineAnimation.SetAnimation("tracks/empty", loop: true, 1);
			}
		}

		public override async Task AfterAddedToRoom()
		{
			await base.AfterAddedToRoom();
			Amalgam = base.CombatState.Enemies.First((Creature c) => c.Monster is TorchHeadAmalgam);
			NRunMusicController.Instance?.UpdateMusicParameter("queen_progress", 1f);
		}

		protected override MonsterMoveStateMachine GenerateMoveStateMachine()
		{
			List<MonsterState> list = new List<MonsterState>();
			MoveState moveState = new MoveState("PUPPET_STRINGS_MOVE", PuppetStringsMove, new CardDebuffIntent());
			MoveState moveState2 = new MoveState("YOU_ARE_MINE_MOVE", YoureMineMove, new DebuffIntent());
			ConditionalBranchState conditionalBranchState = new ConditionalBranchState("YOURE_MINE_NOW_BRANCH");
			BurnBrightForMeState = new MoveState("BURN_BRIGHT_FOR_ME_MOVE", BurnBrightForMeMove, new BuffIntent(), new DefendIntent());
			ConditionalBranchState conditionalBranchState2 = new ConditionalBranchState("BURN_BRIGHT_FOR_ME_BRANCH");
			MoveState moveState3 = new MoveState("OFF_WITH_YOUR_HEAD_MOVE", OffWithYourHeadMove, new MultiAttackIntent(OffWithYourHeadDamage, 5));
			MoveState moveState4 = new MoveState("EXECUTION_MOVE", ExecutionMove, new SingleAttackIntent(ExecutionDamage));
			EnragedState = new MoveState("ENRAGE_MOVE", EnrageMove, new BuffIntent());
			moveState.FollowUpState = moveState2;
			moveState2.FollowUpState = conditionalBranchState;
			conditionalBranchState.AddState(BurnBrightForMeState, () => !HasAmalgamDied);
			conditionalBranchState.AddState(moveState3, () => HasAmalgamDied);
			BurnBrightForMeState.FollowUpState = conditionalBranchState2;
			conditionalBranchState2.AddState(BurnBrightForMeState, () => !HasAmalgamDied);
			conditionalBranchState2.AddState(moveState3, () => HasAmalgamDied);
			moveState3.FollowUpState = moveState4;
			moveState4.FollowUpState = EnragedState;
			EnragedState.FollowUpState = moveState3;
			list.Add(moveState);
			list.Add(moveState2);
			list.Add(BurnBrightForMeState);
			list.Add(conditionalBranchState2);
			list.Add(conditionalBranchState);
			list.Add(moveState3);
			list.Add(moveState4);
			list.Add(EnragedState);
			return new MonsterMoveStateMachine(list, moveState);
		}

		private async Task PuppetStringsMove(IReadOnlyList<Creature> targets)
		{
			SfxCmd.Play("event:/sfx/enemy/enemy_attacks/queen/queen_cast");
			await CreatureCmd.TriggerAnim(base.Creature, "Cast", 0.5f);
			await PowerCmd.Apply<ChainsOfBindingPower>(new ThrowingPlayerChoiceContext(), targets, 3m, base.Creature, null);
		}

		private async Task YoureMineMove(IReadOnlyList<Creature> targets)
		{
			LocString line = MonsterModel.L10NMonsterLookup("QUEEN.banter");
			TalkCmd.Play(line, base.Creature, VfxColor.Purple);
			SfxCmd.Play("event:/sfx/enemy/enemy_attacks/queen/queen_cast");
			await CreatureCmd.TriggerAnim(base.Creature, "Cast", 0.5f);
			await PowerCmd.Apply<FrailPower>(new ThrowingPlayerChoiceContext(), targets, 99m, base.Creature, null);
			await PowerCmd.Apply<WeakPower>(new ThrowingPlayerChoiceContext(), targets, 99m, base.Creature, null);
			await PowerCmd.Apply<VulnerablePower>(new ThrowingPlayerChoiceContext(), targets, 99m, base.Creature, null);
		}

		private async Task BurnBrightForMeMove(IReadOnlyList<Creature> targets)
		{
			SfxCmd.Play("event:/sfx/enemy/enemy_attacks/queen/queen_cast");
			await CreatureCmd.TriggerAnim(base.Creature, "Cast", 0.8f);
			int strengthAmount = AscensionHelper.GetValueIfAscension(AscensionLevel.DeadlyEnemies, 1, 1);
			List<Creature> source = base.CombatState.GetTeammatesOf(base.Creature).ToList();
			foreach (Creature item in source.Where((Creature teammate) => teammate != base.Creature))
			{
				await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), item, strengthAmount, base.Creature, null);
			}
			await CreatureCmd.GainBlock(base.Creature, 20m, ValueProp.Move, null);
		}

		private async Task OffWithYourHeadMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(OffWithYourHeadDamage).WithHitCount(5).FromMonster(this)
				.WithAttackerAnim("Attack", 0.6f)
				.OnlyPlayAnimOnce()
				.WithAttackerFx(null, AttackSfx)
				.WithHitFx("vfx/vfx_attack_blunt")
				.Execute(null);
		}

		private async Task ExecutionMove(IReadOnlyList<Creature> targets)
		{
			await DamageCmd.Attack(ExecutionDamage).FromMonster(this).WithAttackerAnim("Attack", 0.6f)
				.OnlyPlayAnimOnce()
				.WithAttackerFx(null, AttackSfx)
				.WithHitFx("vfx/vfx_attack_blunt")
				.Execute(null);
		}

		private async Task EnrageMove(IReadOnlyList<Creature> targets)
		{
			SfxCmd.Play("event:/sfx/enemy/enemy_attacks/queen/queen_cast");
			await CreatureCmd.TriggerAnim(base.Creature, "Cast", 0.5f);
			await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), base.Creature, 2m, base.Creature, null);
		}

		public override Task AfterDeath(PlayerChoiceContext choiceContext, Creature creature, bool wasRemovalPrevented, float deathAnimLength)
		{
			if (creature.Monster is TorchHeadAmalgam && base.Creature.IsAlive)
			{
				NRunMusicController.Instance?.UpdateMusicParameter("queen_progress", 2f);
				HasAmalgamDied = true;
				Amalgam = null;
				LocString line = MonsterModel.L10NMonsterLookup("QUEEN.amalgamDeathSpeakLine");
				TalkCmd.Play(line, base.Creature, VfxColor.Purple);
				if (base.NextMove == BurnBrightForMeState)
				{
					SetMoveImmediate(EnragedState);
				}
			}
			if (creature == base.Creature)
			{
				NRunMusicController.Instance?.UpdateMusicParameter("queen_progress", 5f);
				base.Creature.GetCreatureNode()?.SpineAnimation.SetAnimation("tracks/empty", loop: true, 1);
			}
			return Task.CompletedTask;
		}

		protected override bool ShouldShowMoveInBestiary(string moveStateId)
		{
			if (moveStateId != "PUPPET_STRINGS_MOVE" && moveStateId != "BURN_BRIGHT_FOR_ME_MOVE" && moveStateId != "ENRAGE_MOVE")
			{
				return moveStateId != "EXECUTION_MOVE";
			}
			return false;
		}
	}
