				.WithAttackerAnim("AttackTripleTrigger", 0.25f)
				.OnlyPlayAnimOnce()
				.WithAttackerFx(null, "event:/sfx/enemy/enemy_attacks/terror_eel/terror_eel_attack_multi")
				.WithHitFx("vfx/vfx_attack_slash")
				.Execute(null);
