		private async Task Revive(int baseRespawnHp)
		{
			AssertMutable();
			decimal scaledHp = MegaCrit.Sts2.Core.Entities.Creatures.Creature.ScaleHpForMultiplayer(baseRespawnHp, base.CombatState.Encounter, base.CombatState.Players.Count, base.CombatState.RunState.CurrentActIndex);
			await CreatureCmd.SetMaxHp(base.Creature, scaledHp);
			await CreatureCmd.Heal(base.Creature, scaledHp);
		}

		private void SetColor(Color color)
		{
			//IL_002b: Unknown result type (might be due to invalid IL or missing references)
			NCreature nCreature = NCombatRoom.Instance?.GetCreatureNode(base.Creature);
			if (nCreature != null)
			{
				CanvasGroup? specialNode = nCreature.GetSpecialNode<CanvasGroup>("%CanvasGroup");
				if (specialNode != null)
				{
					((CanvasItem)specialNode).SetSelfModulate(color);
				}
			}
		}

		public override CreatureAnimator GenerateAnimator(MegaSprite controller)
		{
			AnimState animState = new AnimState("idle_loop1", isLooping: true);
			AnimState animState2 = new AnimState("hurt1");
			AnimState animState3 = new AnimState("attack_double1");
			AnimState animState4 = new AnimState("attack_big1");
			AnimState animState5 = new AnimState("heal1");
			AnimState animState6 = new AnimState("knockout1");
