			MoveState moveState2 = new MoveState("NAB_MOVE", NabMove, new SingleAttackIntent(NabDamage));
			MoveState moveState3 = new MoveState("HAT_TRICK_MOVE", HatTrickMove, new SingleAttackIntent(HatTrickDamage));
