			creatureAnimator.AddAnyState("Attack", animState4, () => !IsHovering);
			creatureAnimator.AddAnyState("Flee", state2, () => IsHovering);
			creatureAnimator.AddAnyState("Flee", state, () => !IsHovering);
			return creatureAnimator;
