		public void ScaleTo(float scale, float duration)
		{
			//IL_004f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
			//IL_005a: Unknown result type (might be due to invalid IL or missing references)
			Node2D val = base.Creature.GetCreatureNode()?.GetSpecialNode<Node2D>("Visuals/ScalingBone");
			if (val != null)
			{
				ScaleTween?.FastForwardToCompletion();
				ScaleTween = ((Node)val).CreateTween();
				ScaleTween.TweenProperty((GodotObject)(object)val, NodePath.op_Implicit("scale"), Variant.op_Implicit(Vector2.One * scale), (double)duration).SetEase((EaseType)2).SetTrans((TransitionType)1);
			}
		}

