		private static async Task ObtainCards(Player player, Rng rng)
		{
			List<CardPileAddResult> results = new List<CardPileAddResult>();
			for (int i = 0; i < 5; i++)
			{
				CardCreationOptions options = CardCreationOptions.ForNonCombatWithUniformOdds(new global::<>z__ReadOnlySingleElementList<CardPoolModel>(ModelDb.CardPool<ColorlessCardPool>())).WithFlags(CardCreationFlags.NoRarityModification | CardCreationFlags.NoCardPoolModifications);
				CardModel card = CardFactory.CreateForReward(player, 1, options).First().Card;
				results.Add(await CardPileCmd.Add(card, PileType.Deck));
			}
