			EventOption eventOption2 = ((gold < base.DynamicVars["EmotionalAwarenessCost"].IntValue) ? CreateLockedOption() : new EventOption(this, EmotionalAwareness, "ZEN_WEAVER.pages.INITIAL.options.EMOTIONAL_AWARENESS"));
