		public override Task BeforeFlush(PlayerChoiceContext choiceContext, Player player)
		{
			if (player != base.Card.Owner)
			{
				return Task.CompletedTask;
			}
			CardPile? pile = base.Card.Pile;
			if (pile == null || pile.Type != PileType.Hand)
			{
				return Task.CompletedTask;
			}
			base.Card.EnergyCost.AddUntilPlayed(-1);
			return Task.CompletedTask;
		}
	}
	public sealed class SoulsPower : EnchantmentModel
	{
		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromKeyword(CardKeyword.Exhaust));

		public override bool CanEnchant(CardModel card)
		{
			if (!base.CanEnchant(card))
			{
				return false;
			}
			if (!card.GetKeywordsWithSources(KeywordSources.Local).Contains(CardKeyword.Exhaust))
			{
				return false;
			}
			return true;
		}

		protected override void OnEnchant()
		{
			CardCmd.RemoveKeyword(base.Card, CardKeyword.Exhaust);
		}
	}
	public sealed class Sown : EnchantmentModel
	{
		public override bool HasExtraCardText => true;

		public override async Task OnPlay(PlayerChoiceContext choiceContext, CardPlay? cardPlay)
		{
			if (base.Status == EnchantmentStatus.Normal)
			{
				base.Status = EnchantmentStatus.Disabled;
				await PlayerCmd.GainEnergy(base.Amount, base.Card.Owner);
			}
		}
	}
	public sealed class Spiral : EnchantmentModel
	{
		private const string _timesKey = "Times";

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new IntVar("Times", 1m));

		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.Static(StaticHoverTip.ReplayDynamic, base.DynamicVars["Times"]));

		public override bool CanEnchant(CardModel c)
		{
			if (base.CanEnchant(c) && c.Rarity == CardRarity.Basic)
			{
				if (!c.Tags.Contains(CardTag.Strike))
				{
					return c.Tags.Contains(CardTag.Defend);
				}
				return true;
			}
			return false;
		}

		public override int EnchantPlayCount(int originalPlayCount)
		{
			return originalPlayCount + base.DynamicVars["Times"].IntValue;
		}
	}
	public sealed class Steady : EnchantmentModel
	{
