				await CardPileCmd.Draw(choiceContext, base.Amount, base.Card.Owner);
			}
		}
	}
	public sealed class TezcatarasEmber : EnchantmentModel
	{
		protected override IEnumerable<IHoverTip> ExtraHoverTips => new global::<>z__ReadOnlySingleElementList<IHoverTip>(HoverTipFactory.FromKeyword(CardKeyword.Eternal));

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlySingleElementList<DynamicVar>(new DamageVar(3m, ValueProp.Move));

		protected override void OnEnchant()
		{
			base.Card.EnergyCost.UpgradeBy(-base.Card.EnergyCost.GetWithModifiers(CostModifiers.None));
			base.Card.AddKeyword(CardKeyword.Eternal);
		}

		public override decimal EnchantDamageAdditive(decimal originalDamage, ValueProp props)
		{
			if (!props.IsPoweredAttack())
			{
				return 0m;
			}
			return base.DynamicVars.Damage.BaseValue;
		}
	}
	public sealed class Vigorous : EnchantmentModel
	{
		public override bool ShowAmount => true;

		public override bool CanEnchantCardType(CardType cardType)
		{
			return cardType == CardType.Attack;
		}

		public override decimal EnchantDamageAdditive(decimal originalDamage, ValueProp props)
		{
			if (base.Status != EnchantmentStatus.Normal)
			{
				return 0m;
			}
			if (!props.IsPoweredAttack())
			{
				return 0m;
			}
			return base.Amount;
		}

		public override Task AfterCardPlayed(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (cardPlay.Card != base.Card)
			{
				return Task.CompletedTask;
			}
			base.Status = EnchantmentStatus.Disabled;
			return Task.CompletedTask;
		}
	}
}
