namespace MegaCrit.Sts2.Core.Models.Cards.Mocks
{
	public sealed class MockAttackCard : MockCardModel
	{
		private int _hitCount = 1;

		private bool _fromOsty;

		private TargetType _targetingType = TargetType.AnyEnemy;

		public override CardType Type => CardType.Attack;

		public override TargetType TargetType => _targetingType;

		protected override IEnumerable<DynamicVar> CanonicalVars => new global::<>z__ReadOnlyArray<DynamicVar>(new DynamicVar[3]
		{
			new DamageVar(6m, ValueProp.Move),
			new OstyDamageVar(6m, ValueProp.Move),
			new BlockVar(0m, ValueProp.Move)
		});

		public override MockAttackCard MockBlock(int block)
		{
			AssertMutable();
			base.DynamicVars.Block.BaseValue = block;
			return this;
		}

		public MockAttackCard MockDamage(decimal damage)
		{
			AssertMutable();
			base.DynamicVars.Damage.BaseValue = damage;
			return this;
		}

		public MockAttackCard MockOstyDamage(decimal damage)
		{
			AssertMutable();
			base.DynamicVars.OstyDamage.BaseValue = damage;
			return this;
		}

		public MockAttackCard MockHitCount(int hitCount)
		{
			AssertMutable();
			_hitCount = hitCount;
			return this;
		}

		public MockAttackCard MockFromOsty()
		{
			AssertMutable();
			_fromOsty = true;
			MockTag(CardTag.OstyAttack);
			return this;
		}

		public MockAttackCard MockTargetingType(TargetType targetingType)
		{
			AssertMutable();
			_targetingType = targetingType;
			return this;
		}

		public MockAttackCard MockUnpoweredDamage()
		{
			AssertMutable();
			base.DynamicVars.Damage.Props = ValueProp.Unpowered;
			base.DynamicVars.OstyDamage.Props = ValueProp.Unpowered;
			return this;
		}

		protected override int GetBaseBlock()
		{
			return base.DynamicVars.Block.IntValue;
		}

		protected override async Task OnPlay(PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			if (_mockSelfHpLoss > 0)
			{
				await CreatureCmd.Damage(choiceContext, base.Owner.Creature, _mockSelfHpLoss, ValueProp.Unblockable | ValueProp.Unpowered | ValueProp.Move, this, cardPlay);
			}
			if (base.DynamicVars.Block.BaseValue > 0m)
			{
				await CreatureCmd.GainBlock(base.Owner.Creature, base.DynamicVars.Block, cardPlay);
			}
			int hitCount = (base.EnergyCost.CostsX ? ResolveEnergyXValue() : ((!HasStarCostX) ? _hitCount : ResolveStarXValue()));
			AttackCommand attackCommand = DamageCmd.Attack(_fromOsty ? base.DynamicVars.OstyDamage.BaseValue : base.DynamicVars.Damage.BaseValue).WithHitCount(hitCount);
			if (_fromOsty)
			{
				if (Osty.CheckMissingWithAnim(base.Owner))
				{
					return;
				}
				attackCommand = attackCommand.FromOsty(base.Owner.Osty, this, cardPlay);
			}
			else
			{
				attackCommand = attackCommand.FromCard(this, cardPlay);
			}
			switch (_targetingType)
			{
			case TargetType.AnyEnemy:
				ArgumentNullException.ThrowIfNull(cardPlay.Target, "cardPlay.Target");
				attackCommand = attackCommand.Targeting(cardPlay.Target);
				break;
			case TargetType.AllEnemies:
				attackCommand = attackCommand.TargetingAllOpponents(base.CombatState);
				break;
			case TargetType.RandomEnemy:
				attackCommand = attackCommand.TargetingRandomOpponents(base.CombatState);
				break;
			default:
				throw new ArgumentOutOfRangeException();
			}
			if (base.DynamicVars.Damage.Props.HasFlag(ValueProp.Unpowered))
			{
				attackCommand = attackCommand.Unpowered();
			}
			await attackCommand.Execute(choiceContext);
			if (_mockExtraLogic != null)
			{
				await _mockExtraLogic(this);
			}
		}

		protected override void OnUpgrade()
		{
			if (_mockUpgradeLogic != null)
			{
				_mockUpgradeLogic(this);
			}
			else
			{
				base.DynamicVars.Damage.UpgradeValueBy(3m);
			}
		}
	}
	public abstract class MockCardModel : CardModel
	{
		protected int _mockEnergyCost = 1;

		protected CardMultiplayerConstraint _mockMultiplayerConstraint;

		protected bool _mockEnergyCostX;

		protected int _mockStarCost;

		protected bool _mockStarCostX;

		protected Func<CardModel, Task>? _mockExtraLogic;

		protected int _mockMaxUpgradeLevel = 1;

		protected CardRarity _mockRarity = CardRarity.Common;

		protected int _mockSelfHpLoss;

		protected HashSet<CardTag>? _mockTags;

		protected CardPoolModel? _mockPool;

		protected Action<CardModel>? _mockUpgradeLogic;

		public override bool IsMock => true;

		protected override int CanonicalEnergyCost => _mockEnergyCost;

		protected override bool HasEnergyCostX => _mockEnergyCostX;

		public override int CanonicalStarCost => _mockStarCost;

		public override bool HasStarCostX => _mockStarCostX;

		public override CardMultiplayerConstraint MultiplayerConstraint => _mockMultiplayerConstraint;

		public override bool GainsBlock => GetBaseBlock() > 0;

		public override int MaxUpgradeLevel => _mockMaxUpgradeLevel;

		public override CardRarity Rarity => _mockRarity;

		public override CardPoolModel Pool => _mockPool ?? ModelDb.CardPool<DeprivedCardPool>();

		public override IEnumerable<CardTag> Tags => _mockTags ?? new HashSet<CardTag>();

		protected MockCardModel()
			: base(1, CardType.Attack, CardRarity.Common, TargetType.AnyEnemy)
		{
		}

		public abstract MockCardModel MockBlock(int block);

		public MockCardModel MockCanonical()
		{
			AssertMutable();
			base.CombatState?.RemoveCard(this);
			NeverEverCallThisOutsideOfTests_ClearOwner();
			NeverEverCallThisOutsideOfTests_SetIsMutable(isMutable: false);
			return this;
		}

		public MockCardModel MockEnergyCost(int cost)
		{
			AssertMutable();
			_mockEnergyCost = cost;
			_mockEnergyCostX = false;
			MockSetEnergyCost(new CardEnergyCost(this, cost, costsX: false));
			return this;
		}

		public MockCardModel MockMultiplayerType(CardMultiplayerConstraint constraint)
		{
			AssertMutable();
			_mockMultiplayerConstraint = constraint;
			return this;
		}

		public MockCardModel MockEnergyCostX()
		{
			AssertMutable();
			_mockEnergyCostX = true;
			_mockEnergyCost = 0;
			MockSetEnergyCost(new CardEnergyCost(this, 0, costsX: true));
			return this;
		}

		public MockCardModel MockStarCost(int cost)
		{
			AssertMutable();
			_mockStarCost = cost;
			_mockStarCostX = false;
			return this;
		}

		public MockCardModel MockStarCostX()
		{
			AssertMutable();
			_mockStarCostX = true;
			_mockStarCost = 0;
			return this;
		}

		public MockCardModel MockExtraLogic(Func<CardModel, Task> extraLogic)
		{
			AssertMutable();
			_mockExtraLogic = extraLogic;
			return this;
		}

		public MockCardModel MockKeyword(CardKeyword keyword)
		{
			AssertMutable();
			AddKeyword(keyword);
			return this;
		}

		public MockCardModel MockReplay(int count)
		{
			AssertMutable();
			base.BaseReplayCount = count;
			return this;
		}

		public MockCardModel MockRarity(CardRarity rarity)
		{
			AssertMutable();
			_mockRarity = rarity;
			return this;
		}

		public MockCardModel MockPool<T>() where T : CardPoolModel
		{
			AssertMutable();
			_mockPool = ModelDb.CardPool<T>();
			return this;
		}

		public MockCardModel MockTag(CardTag tag)
		{
			AssertMutable();
			if (_mockTags == null)
			{
				_mockTags = new HashSet<CardTag>();
			}
			_mockTags.Add(tag);
			return this;
		}

		public MockCardModel MockSelfHpLoss(int hpLoss)
		{
			AssertMutable();
			_mockSelfHpLoss = hpLoss;
			return this;
		}

		public MockCardModel MockUnUpgradable()
		{
			AssertMutable();
			_mockMaxUpgradeLevel = 0;
			return this;
		}

		public MockCardModel MockUpgradeLogic(Action<CardModel> upgradeLogic)
		{
			AssertMutable();
			_mockUpgradeLogic = upgradeLogic;
			return this;
		}

		protected abstract int GetBaseBlock();
	}
