		{
			return FileAccess.FileExists(path);
		}

		public bool DirectoryExists(string path)
		{
			return DirAccess.DirExistsAbsolute(path);
		}

		public Stream OpenStream(string path, ModeFlags mode)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			return new FileAccessStream(path, mode);
		}

		public void MakeDirRecursive(string path)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			DirAccess.MakeDirRecursiveAbsolute(path);
		}

		public Error CopyFile(string sourcePath, string destinationPath)
		{
			//IL_0003: Unknown result type (might be due to invalid IL or missing references)
			return DirAccess.CopyAbsolute(sourcePath, destinationPath, -1);
		}
	}
	public enum ModManagerState
	{
		None,
		Initialized,
		Skipped
	}
	public record ModManifest
	{
		[JsonPropertyName("id")]
		public string? id;

		[JsonPropertyName("name")]
		public string? name;

		[JsonPropertyName("author")]
		public string? author;

		[JsonPropertyName("description")]
		public string? description;

		[JsonPropertyName("version")]
		public string? version;

		[JsonPropertyName("has_pck")]
		public bool hasPck;

		[JsonPropertyName("has_dll")]
		public bool hasDll;

		[JsonPropertyName("dependencies")]
		public List<ModDependency>? dependencies;

		[JsonPropertyName("affects_gameplay")]
		public bool affectsGameplay = true;

		[JsonPropertyName("min_game_version")]
		public string? minGameVersion;

		public static ModManifest? ReadFromStream(Stream stream, out List<LocString>? errors)
		{
			errors = null;
			JsonNode jsonNode = JsonNode.Parse(stream);
			if (jsonNode == null)
			{
				return null;
			}
			JsonNode jsonNode2 = jsonNode["dependencies"];
			if (jsonNode2 != null && jsonNode2.GetValueKind() == JsonValueKind.Array)
			{
				JsonNode? jsonNode3 = jsonNode2.AsArray().FirstOrDefault();
				if (jsonNode3 != null && jsonNode3.GetValueKind() == JsonValueKind.String)
				{
					Log.Error("Detected old-style dependencies without min version specified! It works for now but this will be removed in a future release. Let the mod author know.");
					LocString locString = new LocString("main_menu_ui", "MOD_ERROR.MIGRATION_REQUIRED");
					locString.Add("id", jsonNode["id"]?.GetValue<string>() ?? "<null>");
					if (errors == null)
					{
						errors = new List<LocString>();
					}
					errors.Add(locString);
					JsonArray jsonArray = new JsonArray();
					foreach (JsonNode item in jsonNode2.AsArray())
					{
						if (item != null)
						{
							jsonArray.Add(new JsonObject(new global::<>z__ReadOnlyArray<KeyValuePair<string, JsonNode>>(new KeyValuePair<string, JsonNode>[2]
							{
								new KeyValuePair<string, JsonNode>("id", item.GetValue<string>()),
								new KeyValuePair<string, JsonNode>("min_version", null)
							})));
						}
					}
					jsonNode["dependencies"] = jsonArray;
				}
			}
			return jsonNode.Deserialize(JsonSerializationUtility.GetTypeInfo<ModManifest>());
		}
	}
	public class ModSettings
	{
		[JsonPropertyName("mods_enabled")]
		public bool PlayerAgreedToModLoading { get; set; }

		[JsonPropertyName("mod_list")]
		[JsonSerializeCondition(SerializationCondition.SaveIfNotCollectionEmptyOrNull)]
		public List<SettingsSaveMod> ModList { get; set; } = new List<SettingsSaveMod>();

		public bool IsModDisabled(Mod mod)
		{
			return IsModDisabled(mod.manifest?.id, mod.modSource);
		}

		public bool IsModDisabled(string? id, ModSource source)
		{
			return ModList.Any((SettingsSaveMod m) => m.Id == id && m.Source == source && !m.IsEnabled);
		}
	}
	public enum ModSource
	{
		None,
		ModsDirectory,
		SteamWorkshop
	}
	public class SettingsSaveMod
	{
		[JsonPropertyName("id")]
		public string Id { get; set; } = "";

		[JsonPropertyName("source")]
		public ModSource Source { get; set; }

		[JsonPropertyName("is_enabled")]
		public bool IsEnabled { get; set; } = true;

		public SettingsSaveMod()
		{
		}

		public SettingsSaveMod(Mod mod)
		{
			Id = mod.manifest?.id ?? throw new InvalidOperationException();
			Source = mod.modSource;
		}
	}
