		}

		public void Error(string text, int skipFrames = 1)
		{
			LogMessage(LogLevel.Error, text, skipFrames);
		}

		public static void SetLogLevelForType(LogType type, LogLevel? logLevel)
		{
			if (logLevel.HasValue)
			{
