		{
			return ForEnergyWithIconPath(EnergyIconHelper.GetPath(potion));
		}

		public static IHoverTip ForEnergy(PowerModel power)
		{
			return ForEnergyWithIconPath(EnergyIconHelper.GetPath(power));
		}

		public static IHoverTip ForEnergy(Player player)
		{
			return ForEnergyWithIconPath(EnergyIconHelper.GetPath(player.Character.CardPool));
		}

		public static IHoverTip ForEnergy(RelicModel relic)
		{
			return ForEnergyWithIconPath(EnergyIconHelper.GetPath(relic));
		}

		private static IHoverTip ForEnergyWithIconPath(string path)
		{
			string localCharacterEnergyIconPrefix = RunManager.Instance.GetLocalCharacterEnergyIconPrefix();
			return new HoverTip(L10NStatic("ENERGY.title"), L10NStatic("ENERGY.description"), PreloadManager.Cache.GetTexture2D((localCharacterEnergyIconPrefix != null) ? EnergyIconHelper.GetPath(localCharacterEnergyIconPrefix) : path));
		}

		public static IEnumerable<IHoverTip> FromForge()
		{
			List<IHoverTip> list = new List<IHoverTip>();
			list.Add(Static(StaticHoverTip.Forge));
			list.AddRange(FromCardWithCardHoverTips<SovereignBlade>());
			return new <>z__ReadOnlyList<IHoverTip>(list);
		}

		private static LocString L10NStatic(string entry)
		{
			return new LocString("static_hover_tips", entry);
		}
	}
	public interface IHoverTip
	{
		private static readonly string _summonStaticId = HoverTipFactory.Static(StaticHoverTip.SummonStatic).Id;

		private static readonly string _summonDynamicId = HoverTipFactory.Static(StaticHoverTip.SummonDynamic, new SummonVar(0m)).Id;

		string Id { get; }

		bool IsSmart { get; }

		bool IsDebuff { get; }

		bool IsInstanced { get; }

		AbstractModel? CanonicalModel { get; }

		static IEnumerable<IHoverTip> RemoveDupes(IEnumerable<IHoverTip> tips)
		{
			List<IHoverTip> list = new List<IHoverTip>();
			foreach (IHoverTip hoverTip in tips)
			{
				if (string.IsNullOrEmpty(hoverTip.Id))
				{
					list.Add(hoverTip);
					continue;
				}
				IHoverTip hoverTip2 = list.FirstOrDefault((IHoverTip tip) => tip.Id == hoverTip.Id && !tip.IsInstanced);
				if (hoverTip2 == null)
				{
					list.Add(hoverTip);
				}
				else if (!hoverTip2.IsSmart || hoverTip.IsSmart)
				{
					list.Remove(hoverTip2);
					list.Add(hoverTip);
				}
			}
			if (list.Any((IHoverTip tip) => tip.Id == _summonStaticId))
			{
				list.RemoveAll((IHoverTip tip) => tip.Id == _summonDynamicId);
			}
			return list;
		}
	}
	public static class HoverTipExtensions
	{
		public static void MegaTryAddingTip(this ICollection<IHoverTip> tips, IHoverTip tip)
		{
			IHoverTip hoverTip = tips.FirstOrDefault((IHoverTip t) => t.Id == tip.Id);
			if (hoverTip != null && !hoverTip.IsInstanced)
			{
				if (!hoverTip.IsSmart && tip.IsSmart)
				{
					tips.Remove(hoverTip);
					tips.Add(tip);
				}
			}
			else
			{
				tips.Add(tip);
			}
		}
	}
	public enum StaticHoverTip
	{
		None = 0,
		Channeling = 2,
		Evoke = 3,
		Transform = 4,
		Block = 5,
		Fatal = 6,
		Energy = 7,
		Stun = 8,
		CardReward = 9,
		Forge = 10,
		SummonDynamic = 12,
		SummonStatic = 13,
		ReplayDynamic = 14,
		ReplayStatic = 15,
		Cook = 16
	}
}
