	public enum HpLossHookPhase
	{
		None = 0,
		BeforeOsty = 1,
		AfterOsty = 2,
		All = 3
	}
	[Flags]
	public enum ModifyDamageHookType
	{
		None = 0,
		Additive = 2,
		Multiplicative = 4,
		Cap = 8,
		All = 0xE
	}
}
