		private static void TryCollectLinuxCoreDump(ZipArchive archive)
		{
			if (OS.GetName() != "Linux")
			{
				return;
			}
			string fileName = Path.GetFileName(OS.GetExecutablePath());
			try
			{
				using Process process = new Process();
				process.StartInfo = new ProcessStartInfo
				{
					FileName = "coredumpctl",
					Arguments = "info -1 --no-pager " + fileName,
					RedirectStandardOutput = true,
					UseShellExecute = false
				};
				process.Start();
				Task<string> task = process.StandardOutput.ReadToEndAsync();
				if (!task.Wait(10000))
				{
					process.Kill();
					process.WaitForExit(5000);
					Log.Warn("coredumpctl info timed out after 10s");
				}
				else
				{
					string result = task.Result;
					process.WaitForExit();
					if (process.ExitCode == 0 && !string.IsNullOrWhiteSpace(result))
					{
						ZipArchiveEntry zipArchiveEntry = archive.CreateEntry("crashes/coredump_info.txt");
						using StreamWriter streamWriter = new StreamWriter(zipArchiveEntry.Open());
						streamWriter.Write(result);
					}
				}
			}
			catch (Exception ex)
			{
				Log.Warn("Could not collect coredumpctl info: " + ex.Message);
			}
			string text = Path.Combine(Path.GetTempPath(), $"sts2_coredump_{Guid.NewGuid()}.core");
			try
			{
				using Process process2 = new Process();
				process2.StartInfo = new ProcessStartInfo
				{
					FileName = "coredumpctl",
					Arguments = "dump -1 --no-pager -o \"" + text + "\" " + fileName,
					UseShellExecute = false
				};
				process2.Start();
				if (!process2.WaitForExit(10000))
				{
					Log.Warn("coredumpctl dump timed out after 10s, killing process");
					process2.Kill();
					process2.WaitForExit(5000);
				}
				else if (process2.ExitCode != 0)
				{
					Log.Warn($"coredumpctl dump exited with code {process2.ExitCode}");
				}
				if (File.Exists(text))
				{
					long length = new FileInfo(text).Length;
					if (length > 209715200)
					{
						Log.Warn($"Core dump is {length / 1048576} MB which exceeds the {200L} MB limit, skipping");
					}
					else if (length > 0)
					{
						ArchiveFile(text, archive, "crashes/coredump.core");
					}
				}
			}
			catch (Exception ex2)
			{
				Log.Warn("Could not collect core dump: " + ex2.Message);
			}
			finally
			{
				try
				{
					File.Delete(text);
				}
				catch
				{
				}
			}
		}

		private static IEnumerable<string> GetAllSaveFiles(string accountBasePath)
		{
			if (!Directory.Exists(accountBasePath))
			{
				yield break;
			}
			foreach (string item in Directory.EnumerateFiles(accountBasePath, "*", SearchOption.AllDirectories))
			{
				yield return item;
			}
		}

		public static string ReadTailText(Stream stream, long maxBytes)
		{
			bool flag = false;
			if (maxBytes > 0 && stream.Length > maxBytes)
			{
				stream.Seek(stream.Length - maxBytes, SeekOrigin.Begin);
				while (stream.Position < stream.Length)
				{
					int num = stream.ReadByte();
					if (num == -1)
					{
						break;
					}
					if ((num & 0xC0) != 128)
					{
						stream.Seek(-1L, SeekOrigin.Current);
						break;
					}
				}
				flag = true;
			}
			using StreamReader streamReader = new StreamReader(stream, null, detectEncodingFromByteOrderMarks: true, -1, leaveOpen: true);
			string text = streamReader.ReadToEnd();
			if (flag)
			{
				int num2 = text.IndexOf('\n');
				if (num2 >= 0)
				{
					string text2 = text;
					int num3 = num2 + 1;
					text = text2.Substring(num3, text2.Length - num3);
				}
				text = $"[...truncated, showing last ~{maxBytes / 1048576} MB...]\n" + text;
			}
			return text;
		}

		private static void ArchiveLogFile(string file, ZipArchive archive, string entryName, long maxBytes)
		{
			entryName = entryName.Replace("\\", "/");
			ZipArchiveEntry zipArchiveEntry = archive.CreateEntry(entryName);
			try
			{
				using FileStream stream = new FileStream(file, FileMode.Open, FileAccess.Read, FileShare.ReadWrite);
				string text = ReadTailText(stream, maxBytes);
				string value = LogSanitizer.Sanitize(text);
				using StreamWriter streamWriter = new StreamWriter(zipArchiveEntry.Open());
				streamWriter.Write(value);
			}
			catch (FileNotFoundException)
			{
				Log.Error("Could not find file for zipping: " + file);
			}
		}

		private static void ArchiveFile(string file, ZipArchive archive, string entryName)
		{
			entryName = entryName.Replace("\\", "/");
			ZipArchiveEntry zipArchiveEntry = archive.CreateEntry(entryName);
			try
			{
				using FileStream fileStream = new FileStream(file, FileMode.Open, FileAccess.Read, FileShare.ReadWrite);
				using Stream destination = zipArchiveEntry.Open();
				fileStream.CopyTo(destination);
			}
			catch (FileNotFoundException)
			{
				Log.Error("Could not find file for zipping: " + file);
			}
		}

		private static void ArchiveBytes(byte[] bytes, ZipArchive archive, string entryName)
		{
			ZipArchiveEntry zipArchiveEntry = archive.CreateEntry(entryName);
			using Stream stream = zipArchiveEntry.Open();
			stream.Write(bytes);
		}
	}
	public class GodModeConsoleCmd : AbstractConsoleCmd
	{
		private bool _godModeActive;

		private Player? _godModePlayer;

		public override string CmdName => "godmode";

		public override string Args => "";

		public override string Description => "Become invincible!";

		public override bool IsNetworked => true;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			if (issuingPlayer == null || !RunManager.Instance.IsInProgress)
			{
				return new CmdResult(success: false, "A run does not appear to be in progress");
			}
			Task task;
			if (_godModeActive)
			{
				_godModeActive = false;
				CombatManager.Instance.CombatSetUp -= OnCombatSetUp;
				_godModePlayer = null;
				task = DisableGodMode(issuingPlayer);
				return new CmdResult(task, success: true, "Godmode deactivated!");
			}
			_godModeActive = true;
			_godModePlayer = issuingPlayer;
			CombatManager.Instance.CombatSetUp += OnCombatSetUp;
			task = EnableGodMode(issuingPlayer);
			return new CmdResult(task, success: true, "Godmode activated!");
		}

		private void OnCombatSetUp(CombatState combatState)
		{
			if (_godModePlayer != null && RunManager.Instance.IsInProgress)
			{
				Player me = LocalContext.GetMe(combatState.RunState);
				if (me == _godModePlayer)
				{
					TaskHelper.RunSafely(EnableGodMode(_godModePlayer));
				}
			}
		}

		private static async Task DisableGodMode(Player player)
		{
			Creature playerCreature = player.Creature;
			await PowerCmd.Remove<StrengthPower>(playerCreature);
			await PowerCmd.Remove<BufferPower>(playerCreature);
			await PowerCmd.Remove<RegenPower>(playerCreature);
		}

		private static async Task EnableGodMode(Player player)
		{
			Creature playerCreature = player.Creature;
			await PowerCmd.Apply<StrengthPower>(new ThrowingPlayerChoiceContext(), playerCreature, 999999999m, playerCreature, null);
			await PowerCmd.Apply<BufferPower>(new ThrowingPlayerChoiceContext(), playerCreature, 999999999m, playerCreature, null);
			await PowerCmd.Apply<RegenPower>(new ThrowingPlayerChoiceContext(), playerCreature, 999999999m, playerCreature, null);
		}
	}
	public class GoldConsoleCmd : AbstractConsoleCmd
	{
		public override string CmdName => "gold";

		public override string Args => "<amount:int>";

		public override string Description => "Manipulate player gold. Cha-ching!";

		public override bool IsNetworked => true;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			if (args.Length < 1)
			{
				return new CmdResult(success: false, "An amount is required");
			}
			if (!int.TryParse(args[0], out var result))
			{
				return new CmdResult(success: false, "First argument (the gold amount) must be an int.");
			}
			if (issuingPlayer == null || !RunManager.Instance.IsInProgress)
			{
				return new CmdResult(success: false, "A run does not appear to be in progress");
			}
			Task task = PlayerCmd.GainGold(result, issuingPlayer);
			return new CmdResult(task, success: true, $"'{result}' gold added.");
		}
	}
	public class HealConsoleCmd : AbstractConsoleCmd
	{
		public override string CmdName => "heal";

		public override string Args => "<amount:int> [index:int]";

		public override string Description => "Heal the player some amount of HP.";

		public override bool IsNetworked => true;

		public override CmdResult Process(Player? issuingPlayer, string[] args)
		{
			if (args.Length < 1)
			{
				return new CmdResult(success: false, "An amount is required");
			}
			if (!int.TryParse(args[0], out var result))
			{
				return new CmdResult(success: false, "First argument (the heal amount) must be an int.");
			}
			if (!RunManager.Instance.IsInProgress)
			{
				return new CmdResult(success: false, "A run does not appear to be in progress");
			}
			if (result < 0)
			{
				return new CmdResult(success: false, "The heal amount cannot be negative.");
			}
			Creature creature;
			if (args.Length > 1)
			{
				if (!int.TryParse(args[1], out var result2))
				{
					return new CmdResult(success: false, "Arg 2 must be the target index (int), got '" + args[1] + "'.");
				}
				IReadOnlyList<Creature> allies = CombatManager.Instance.DebugOnlyGetState().Allies;
				if (result2 < 0 || result2 >= allies.Count)
				{
					return new CmdResult(success: false, $"Invalid target index {result2}. Valid range: 0-{allies.Count - 1}");
				}
				creature = allies[result2];
			}
			else
			{
				creature = issuingPlayer.Creature;
			}
			Task task = CreatureCmd.Heal(creature, result);
			return new CmdResult(task, success: true, $"Healed '{result}' HP to {creature}.");
		}
	}
	public class InstantConsoleCmd : AbstractConsoleCmd
	{
