					AttachGameState(scope);
					configureScope(scope);
				});
			}
		}

		public static void CaptureMessage(string message, SentryLevel level = (SentryLevel)1, Action<Scope>? configureScope = null)
		{
			//IL_0015: Unknown result type (might be due to invalid IL or missing references)
			//IL_001a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0026: Unknown result type (might be due to invalid IL or missing references)
			//IL_0027: Unknown result type (might be due to invalid IL or missing references)
			//IL_0033: Expected O, but got Unknown
			//IL_0040: Unknown result type (might be due to invalid IL or missing references)
			if (IsEnabled)
			{
				SentryEvent val = new SentryEvent
				{
					Message = SentryMessage.op_Implicit(message),
					Level = level
				};
				SentrySdk.CaptureEvent(val, (Action<Scope>)delegate(Scope scope)
				{
					AttachGameState(scope);
					configureScope?.Invoke(scope);
				});
			}
		}

		public static void SetTag(string key, string value)
