		public static void InitializeForTesting()
		{
			if (IsEnabled)
			{
				return;
			}
			string dsn = GetDsn();
			if (string.IsNullOrEmpty(dsn))
			{
				Log.Warn("[Sentry.NET] Cannot initialize for testing: no DSN configured");
				return;
			}
			SentrySdk.Init((Action<SentryGodotOptions>)delegate(SentryGodotOptions options)
			{
				((SentryOptions)options).Dsn = dsn;
				((SentryOptions)options).Environment = "development";
				((SentryOptions)options).Release = ReleaseInfoManager.Instance.ReleaseInfo?.Version ?? "dev-console-test";
				((SentryOptions)options).Debug = false;
				((SentryOptions)options).AutoSessionTracking = false;
				((SentryOptions)options).IsGlobalModeEnabled = true;
				((SentryOptions)options).SendDefaultPii = false;
			});
			IsEnabled = SentrySdk.IsEnabled;
			if (!IsEnabled)
			{
				Log.Warn("[Sentry.NET] SDK initialization failed for testing");
				return;
			}
			SentrySdk.ConfigureScope((Action<Scope>)delegate(Scope scope)
			{
				scope.SetTag("sdk", "dotnet");
				scope.SetTag("session_id", _sessionId);
				scope.SetTag("source", "dev-console-test");
			});
			Log.Info("[Sentry.NET] Initialized for testing via dev console");
		}

		public static void Shutdown()
		{
			if (IsEnabled)
			{
				Log.LogCallback -= OnLogCallback;
				Log.Info("[Sentry.NET] Shutting down");
				SentrySdk.Close();
				IsEnabled = false;
			}
		}

		private static string GetDsn()
		{
			//IL_000a: Unknown result type (might be due to invalid IL or missing references)
			//IL_000f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0014: Unknown result type (might be due to invalid IL or missing references)
			Variant setting = ProjectSettings.GetSetting("sentry/config/dsn", Variant.op_Implicit(""));
			return ((Variant)(ref setting)).AsString();
		}

		private static void AttachGameState(Scope scope)
		{
			try
			{
				scope.SetExtra("loc.language", (object)LocManager.Instance.Language);
				string currentSceneName = GetCurrentSceneName();
				if (currentSceneName != null)
				{
					scope.SetTag("game.scene", currentSceneName);
				}
				RunState runState = RunManager.Instance.DebugOnlyGetState();
				if (RunManager.Instance.IsInProgress && runState != null)
				{
					scope.SetTag("game.in_run", "true");
					scope.SetExtra("game.seed", (object)runState.Rng.StringSeed);
					scope.SetExtra("game.ascension", (object)runState.AscensionLevel);
					scope.SetExtra("game.act", (object)(runState.CurrentActIndex + 1));
					scope.SetExtra("game.act_name", (object)runState.Act.Id.ToString());
					scope.SetExtra("game.floor", (object)runState.TotalFloor);
					scope.SetExtra("game.mode", (object)runState.GameMode);
					AbstractRoom currentRoom = runState.CurrentRoom;
					scope.SetExtra("game.room_type", (object)currentRoom?.GetType().Name);
					if (currentRoom is EventRoom eventRoom)
					{
						scope.SetExtra("game.event", (object)eventRoom.CanonicalEvent.Id.Entry);
					}
					IReadOnlyList<Player> players = runState.Players;
					if (players.Count > 0)
					{
						scope.SetExtra("game.characters", (object)string.Join(", ", players.Select((Player p) => p.Character.Id)));
						scope.SetExtra("game.player_count", (object)players.Count);
					}
				}
				else
				{
					scope.SetTag("game.in_run", "false");
				}
				CombatState combatState = CombatManager.Instance.DebugOnlyGetState();
				if (combatState != null)
				{
					scope.SetExtra("combat.encounter", (object)combatState.Encounter?.Id.Entry);
					scope.SetExtra("combat.round", (object)combatState.RoundNumber);
					scope.SetExtra("combat.enemy_count", (object)combatState.Enemies.Count);
					scope.SetExtra("combat.enemies", (object)string.Join(", ", combatState.Enemies.Select((Creature e) => e.Monster?.Id.ToString() ?? "unknown")));
					List<string> list = combatState.Players.Select((Player p) => $"{p.Creature.CurrentHp}/{p.Creature.MaxHp}").ToList();
					if (list.Count > 0)
					{
						scope.SetExtra("combat.player_hp", (object)string.Join(", ", list));
					}
				}
			}
			catch
			{
			}
		}

		private static string? GetCurrentSceneName()
		{
			try
			{
				NGame instance = NGame.Instance;
				if (instance == null)
				{
					return null;
				}
				if (instance.MainMenu != null)
				{
					return "MainMenu";
				}
				if (instance.CurrentRunNode != null)
				{
					NRun currentRunNode = instance.CurrentRunNode;
					if (currentRunNode.CombatRoom != null)
					{
						return "CombatRoom";
					}
					if (currentRunNode.MapRoom != null)
					{
						return "MapRoom";
					}
					if (currentRunNode.EventRoom != null)
					{
						return "EventRoom";
					}
					if (currentRunNode.RestSiteRoom != null)
					{
						return "RestSiteRoom";
					}
					if (currentRunNode.MerchantRoom != null)
					{
						return "MerchantRoom";
					}
					if (currentRunNode.TreasureRoom != null)
					{
						return "TreasureRoom";
					}
					return "Run";
				}
				if (instance.LogoAnimation != null)
				{
					return "LogoAnimation";
				}
				return null;
			}
			catch
			{
				return null;
			}
		}

		private static SentryEvent? FilterEvent(SentryEvent sentryEvent)
		{
			if (_suppressAllEvents)
			{
				return null;
			}
			if (sentryEvent.Exception is AutoSlayTimeoutException)
			{
				return null;
			}
			if (!ShouldSampleEvent())
			{
				return null;
			}
			return sentryEvent;
		}

		private static bool ShouldSampleEvent()
		{
			return ShouldSampleEvent(_sampleRate);
		}

		private static bool ShouldSampleEvent(float sampleRate)
		{
			if (System.Random.Shared.NextDouble() >= (double)sampleRate)
			{
				return false;
			}
			if (SaveManager.Instance.IsPrefsLoaded && !SaveManager.Instance.PrefsSave.UploadData)
			{
				return false;
			}
			if (!_isGameInitialized && !ShouldStayAliveAfterInit(shouldLog: false))
			{
				return false;
			}
			return true;
		}

		private static bool ShouldStayAliveAfterInit(bool shouldLog)
		{
			if (IsForcedOn)
			{
				if (shouldLog)
				{
					Log.Info("[Sentry.NET] Staying alive because we're forced on");
				}
				return true;
			}
			if (!SteamInitializer.Initialized)
			{
				if (shouldLog)
				{
					Log.Info("[Sentry.NET] Steam not initialized");
				}
				return false;
			}
			try
			{
				if (SaveManager.Instance.SettingsSave.FullConsole)
				{
					if (shouldLog)
					{
						Log.Info("[Sentry.NET] Full console is on");
					}
					return false;
				}
			}
			catch
			{
				if (shouldLog)
				{
					Log.Info("[Sentry.NET] Exception while checking UploadData or FullConsole");
				}
				return false;
			}
			if (ModManager.IsRunningModded())
			{
				if (shouldLog)
				{
					Log.Info("[Sentry.NET] Is running modded");
				}
				return false;
			}
			LocManager instance = LocManager.Instance;
			if (instance != null && instance.OverridesActive)
			{
				if (shouldLog)
				{
					Log.Info("[Sentry.NET] Loc overrides are active");
				}
				return false;
			}
			if (ModManager.HasHarmonyPatches())
			{
				if (shouldLog)
				{
					Log.Info("[Sentry.NET] Harmony patches active");
				}
				return false;
			}
			return true;
		}
	}
}
namespace MegaCrit.Sts2.Core.Daily
{
	public static class DailyRunUtility
	{
		public static async Task UploadScore(DateTimeOffset time, int score, List<SerializablePlayer> players)
		{
			List<ulong> playerIdsInRun = players.Select((SerializablePlayer p) => p.NetId).ToList();
			if (playerIdsInRun != null && playerIdsInRun.Count == 1 && playerIdsInRun[0] == 1)
			{
				playerIdsInRun[0] = PlatformUtil.GetLocalPlayerId(LeaderboardManager.CurrentPlatform);
			}
			string leaderboardName = GetLeaderboardName(time, players.Count);
			if (!(await ShouldUploadScore(await LeaderboardManager.GetLeaderboard(leaderboardName), playerIdsInRun)))
			{
				Log.Info($"Player already uploaded score for daily {time}, ignoring new score");
				return;
			}
			await LeaderboardManager.UploadLocalScore(await LeaderboardManager.GetOrCreateLeaderboard(leaderboardName), score, playerIdsInRun);
			Log.Info($"Uploaded score of {score} for daily {time} to leaderboard {leaderboardName}");
		}

		public static async Task<bool> ShouldUploadScore(ILeaderboardHandle? handle, List<ulong> playerIdsInRun, CancellationToken cancelToken = default(CancellationToken))
		{
			if (handle == null)
			{
				return true;
			}
			if (playerIdsInRun != null && playerIdsInRun.Count == 1 && playerIdsInRun[0] == 1)
			{
				playerIdsInRun[0] = PlatformUtil.GetLocalPlayerId(LeaderboardManager.CurrentPlatform);
			}
			return (await LeaderboardManager.QueryLeaderboardForUsers(handle, playerIdsInRun, cancelToken)).Count <= 0;
		}

		public static string GetLeaderboardName(DateTimeOffset dateTime, int playerCount)
		{
			PlatformBranch platformBranch = PlatformUtil.GetPlatformBranch();
			bool flag = (uint)(platformBranch - 2) <= 2u;
			if (!flag && NGame.IsReleaseGame())
			{
				return $"{dateTime.Year}_{dateTime.Month:D2}_{dateTime.Day:D2}_{playerCount}p";
			}
			return $"{dateTime.Year}_{dateTime.Month:D2}_{dateTime.Day:D2}_{playerCount}p_BETA";
		}

		public static DateTimeOffset? AddLeaderboardDays(DateTimeOffset day, int days)
		{
			try
			{
				return day + TimeSpan.FromDays(days);
			}
			catch (ArgumentOutOfRangeException)
			{
				return null;
			}
		}
	}
	public static class TimeServer
	{
		private const string _timeServerUrl = "https://time.megacrit.com";

		private const int _maxRetry = 2;

		private const int _waitTimeCap = 4;

		private static readonly Logger _logger = new Logger("TimeServer", LogType.Network);

		public static Task<TimeServerResult?>? RequestTimeTask { get; private set; }

		private static async Task<TimeServerResult?> RequestTime(string url)
		{
			using HttpClient client = new HttpClient
			{
				Timeout = TimeSpan.FromSeconds(5L)
			};
			Exception exception = null;
			int retries = 0;
			while (retries < 2)
			{
				long? num;
				try
				{
					num = await RequestTimeInternal(client, url);
				}
				catch (Exception ex)
				{
					Log.Warn($"Caught exception while requesting server time of type {ex.GetType()}");
					exception = ex;
					num = null;
				}
				if (num.HasValue)
				{
					return new TimeServerResult
					{
						serverTime = DateTimeOffset.FromUnixTimeSeconds(num.Value),
						localReceivedTime = DateTimeOffset.UtcNow
					};
				}
				retries++;
				Log.Info($"Retries: {retries}/{2}");
				if (retries < 2)
				{
					long seconds = Math.Min((long)Math.Pow(2.0, retries), 4L);
					await Task.Delay(TimeSpan.FromSeconds(seconds));
				}
			}
			_logger.Warn("Gave up trying to retrieve server time");
			if (exception != null)
			{
				ExceptionDispatchInfo.Capture(exception).Throw();
			}
			return null;
		}

		private static async Task<long?> RequestTimeInternal(HttpClient client, string url)
		{
			HttpResponseMessage response = await client.GetAsync(url);
			string text = await response.Content.ReadAsStringAsync();
			if (response.IsSuccessStatusCode)
			{
				_logger.Info("Successfully queried time server. Response: " + text);
				if (long.TryParse(text, out var result))
				{
					return result;
				}
			}
			else
			{
				_logger.Info($"Failed to retrieve server time. Status: {response.StatusCode} Response: {text}");
			}
			return null;
		}

		public static Task<TimeServerResult?> FetchDailyTime()
		{
			RequestTimeTask = RequestTime("https://time.megacrit.com");
			return RequestTimeTask;
		}
	}
	public struct TimeServerResult : IPacketSerializable
	{
		public DateTimeOffset serverTime;

		public DateTimeOffset localReceivedTime;

		public void Serialize(PacketWriter writer)
		{
			writer.WriteLong(serverTime.ToUnixTimeSeconds());
			writer.WriteLong(localReceivedTime.ToUnixTimeSeconds());
		}

		public void Deserialize(PacketReader reader)
		{
			serverTime = DateTimeOffset.FromUnixTimeSeconds(reader.ReadLong());
			localReceivedTime = DateTimeOffset.FromUnixTimeSeconds(reader.ReadLong());
		}
	}
