		public static async Task<CardModel?> Draw(PlayerChoiceContext choiceContext, Player player)
		{
			return (await Draw(choiceContext, 1m, player)).FirstOrDefault();
		}

		public static Task<IEnumerable<CardModel>> Draw(PlayerChoiceContext choiceContext, decimal count, Player player, bool fromHandDraw = false)
		{
			return DrawInternal(choiceContext, count, player, fromHandDraw);
		}

		public static Task DrawWithoutBlockingOnOtherPlayers(PlayerChoiceContext choiceContext, decimal count, Player player, CardModel source, bool fromHandDraw = false)
		{
			BranchingPlayerChoiceContext branchingPlayerChoiceContext = new BranchingPlayerChoiceContext(source, LocalContext.NetId.Value, GameActionType.Combat, choiceContext);
			Task<IEnumerable<CardModel>> task = Draw(branchingPlayerChoiceContext, count, player, fromHandDraw);
			return branchingPlayerChoiceContext.AssignTaskAndWaitForPauseOrCompletion(task);
		}

		private static async Task<IEnumerable<CardModel>> DrawInternal(PlayerChoiceContext choiceContext, decimal count, Player player, bool fromHandDraw = false)
		{
			if (CombatManager.Instance.IsOverOrEnding)
			{
				return Array.Empty<CardModel>();
			}
			if (!Hook.ShouldDraw(player.Creature.CombatState, player, fromHandDraw, out AbstractModel modifier))
			{
				await Hook.AfterPreventingDraw(player.Creature.CombatState, modifier);
				return Array.Empty<CardModel>();
			}
			ICombatState combatState = player.Creature.CombatState;
			List<CardModel> result = new List<CardModel>();
			CardPile hand = PileType.Hand.GetPile(player);
			CardPile drawPile = PileType.Draw.GetPile(player);
			int drawsRequested = ((count > 0m) ? ((int)Math.Ceiling(count)) : 0);
			if (drawsRequested == 0)
			{
				return result;
			}
			int num = Math.Max(0, CardPile.MaxCardsInHand - hand.Cards.Count);
			if (num == 0)
			{
				CheckIfDrawIsPossibleAndShowThoughtBubbleIfNot(player);
				return result;
			}
			for (int i = 0; i < drawsRequested; i++)
			{
				if (num <= 0)
				{
					break;
				}
				if (CombatManager.Instance.IsOverOrEnding)
				{
					break;
				}
				if (!CheckIfDrawIsPossibleAndShowThoughtBubbleIfNot(player))
				{
					break;
				}
				await ShuffleIfNecessary(choiceContext, player);
				if (!CheckIfDrawIsPossibleAndShowThoughtBubbleIfNot(player))
				{
					break;
				}
				CardModel card = drawPile.Cards.FirstOrDefault();
				if (card == null || hand.Cards.Count >= CardPile.MaxCardsInHand)
				{
					break;
				}
				result.Add(card);
				await Add(card, hand);
				CombatManager.Instance.History.CardDrawn(combatState, card, fromHandDraw);
				await Hook.AfterCardDrawn(combatState, choiceContext, card, fromHandDraw);
				card.InvokeDrawn();
				NDebugAudioManager.Instance?.Play("card_deal.mp3", 0.25f, PitchVariance.Small);
				num = Math.Max(0, CardPile.MaxCardsInHand - hand.Cards.Count);
			}
			return result;
		}

		public static async Task Shuffle(PlayerChoiceContext choiceContext, Player player)
		{
			if (CombatManager.Instance.IsOverOrEnding)
			{
				return;
			}
			CardPile pile = PileType.Draw.GetPile(player);
			List<CardModel> list = PileType.Discard.GetPile(player).Cards.ToList();
			float timeBetweenCardAdds = Mathf.Min(0.045f, 0.8f / (float)list.Count);
			float randomTimeBetweenCardAdds = 1.11f * timeBetweenCardAdds;
			HashSet<CardModel> drawPileCards = pile.Cards.ToHashSet();
			list.AddRange(drawPileCards);
			list.StableShuffle(player.RunState.Rng.Shuffle);
			Hook.ModifyShuffleOrder(player.Creature.CombatState, player, list, isInitialShuffle: false);
			if (CombatManager.Instance.DebugForcedTopCardOnNextShuffle != null)
			{
				if (!list.Remove(CombatManager.Instance.DebugForcedTopCardOnNextShuffle))
				{
					throw new InvalidOperationException("Could not find card " + CombatManager.Instance.DebugForcedTopCardOnNextShuffle.Id.Entry + " in discard pile.");
				}
				list.Insert(0, CombatManager.Instance.DebugForcedTopCardOnNextShuffle);
				CombatManager.Instance.DebugClearForcedTopCardOnNextShuffle();
			}
			float waitTimeAccumulator = 0f;
			IReadOnlyList<CardPileAddResult> readOnlyList = await Add(list, pile, CardPilePosition.Bottom, null, skipVisuals: true);
			List<Tween> tweens = new List<Tween>();
			foreach (CardPileAddResult item in readOnlyList)
			{
				if (drawPileCards.Contains(item.cardAdded))
				{
					continue;
				}
				var (val, flag) = GetTweenForCardsChangingPiles(new global::<>z__ReadOnlySingleElementList<CardPileAddResult>(item), fromSilentAdd: true);
				if (val != null)
				{
					tweens.Add(val);
				}
				if (val != null || flag)
				{
					float num = timeBetweenCardAdds + Rng.Chaotic.NextFloat((0f - randomTimeBetweenCardAdds) * 0.5f, randomTimeBetweenCardAdds * 0.5f);
					waitTimeAccumulator += num;
					if ((double)waitTimeAccumulator >= ((Node)((SceneTree)Engine.GetMainLoop()).Root).GetProcessDeltaTime())
					{
						await Cmd.Wait(num);
						waitTimeAccumulator = 0f;
					}
				}
			}
			foreach (Tween item2 in tweens)
			{
				if (item2.IsRunning() && await item2.AwaitFinished((Node)(object)NCombatRoom.Instance))
				{
					return;
				}
			}
			await Cmd.CustomScaledWait(0.2f, 0.5f);
			if (!CombatManager.Instance.IsOverOrEnding)
			{
				await Hook.AfterShuffle(player.Creature.CombatState, choiceContext, player);
			}
		}

		public static async Task AutoPlayFromDrawPile(PlayerChoiceContext choiceContext, Player player, int count, CardPilePosition position, bool forceExhaust)
		{
			if (CombatManager.Instance.IsOverOrEnding)
			{
				return;
			}
			List<CardModel> cards = new List<CardModel>(count);
			CardPile drawPile = PileType.Draw.GetPile(player);
			for (int i = 0; i < count; i++)
			{
				await ShuffleIfNecessary(choiceContext, player);
				CardModel cardModel = position switch
				{
					CardPilePosition.Bottom => drawPile.Cards.LastOrDefault(), 
					CardPilePosition.Top => drawPile.Cards.FirstOrDefault(), 
					CardPilePosition.Random => player.RunState.Rng.CombatCardSelection.NextItem(drawPile.Cards), 
					_ => throw new ArgumentOutOfRangeException("position", position, null), 
				};
				if (cardModel == null)
				{
					break;
				}
				cards.Add(cardModel);
				await Add(cardModel, PileType.Play);
			}
			foreach (CardModel item in cards)
			{
				if (!item.Owner.Creature.IsDead)
				{
					item.ExhaustOnNextPlay = forceExhaust;
					await CardCmd.AutoPlay(choiceContext, item, null);
					continue;
				}
				break;
			}
		}

		public static async Task ShuffleIfNecessary(PlayerChoiceContext choiceContext, Player player)
		{
			CardPile pile = PileType.Draw.GetPile(player);
			CardPile pile2 = PileType.Discard.GetPile(player);
			if (!pile.Cards.Any() && pile2.Cards.Any())
			{
				await ShuffleFtueCheck();
				await Shuffle(choiceContext, player);
			}
		}

		private static async Task ShuffleFtueCheck()
		{
			if (!SaveManager.Instance.SeenFtue("shuffle_ftue") && NModalContainer.Instance != null)
			{
				NShuffleFtue nShuffleFtue = NShuffleFtue.Create();
				NModalContainer.Instance.Add((Node)(object)nShuffleFtue);
				SaveManager.Instance.MarkFtueAsComplete("shuffle_ftue");
				await nShuffleFtue.WaitForPlayerToConfirm();
			}
		}

		public static async Task AddToCombatAndPreview<T>(IEnumerable<Creature> targets, PileType pileType, int count, Player? creator, CardPilePosition position = CardPilePosition.Bottom) where T : CardModel
		{
			foreach (Creature target in targets)
			{
				await AddToCombatAndPreview<T>(target, pileType, count, creator, position);
			}
		}

		public static async Task AddToCombatAndPreview<T>(Creature target, PileType pileType, int count, Player? creator, CardPilePosition position = CardPilePosition.Bottom) where T : CardModel
		{
			Player player = target.Player ?? target.PetOwner;
			if (player.Creature.IsDead)
			{
				return;
			}
			CardPileAddResult[] statusCards = new CardPileAddResult[count];
			for (int i = 0; i < count; i++)
			{
				ICombatState? combatState = target.CombatState;
				CardModel cardModel = ((combatState != null) ? combatState.CreateCard<T>(player) : null);
				if (cardModel != null)
				{
					CardPileAddResult[] array = statusCards;
					int num = i;
					array[num] = await AddGeneratedCardToCombat(cardModel, pileType, creator, position);
				}
			}
			if (LocalContext.IsMe(player))
			{
				if (pileType == PileType.Hand)
				{
					await Cmd.Wait(0.1f);
					return;
				}
				CardPreviewStyle style = ((statusCards.Length <= 5) ? CardPreviewStyle.HorizontalLayout : CardPreviewStyle.MessyLayout);
				CardCmd.PreviewCardPileAdd(statusCards, 1.2f, style);
				await Cmd.Wait(1f);
			}
		}

		public static async Task<CardModel?> AddCurseToDeck<T>(Player owner) where T : CardModel
		{
			return (await AddCursesToDeck(new global::<>z__ReadOnlySingleElementList<CardModel>(ModelDb.Card<T>()), owner)).FirstOrDefault().cardAdded;
		}

		public static async Task<IEnumerable<CardPileAddResult>> AddCursesToDeck(IEnumerable<CardModel> curses, Player owner)
		{
			List<CardPileAddResult> results = new List<CardPileAddResult>();
			foreach (CardModel curse in curses)
			{
				if (curse.Type != CardType.Curse)
				{
					throw new ArgumentException(curse.Id.Entry + " is not a curse");
				}
				CardModel card = owner.RunState.CreateCard(curse, owner);
				results.Add(await Add(card, PileType.Deck));
			}
			CardCmd.PreviewCardPileAdd(results, 2f);
			return results;
		}

		private static bool CheckIfDrawIsPossibleAndShowThoughtBubbleIfNot(Player player)
		{
			if (PileType.Draw.GetPile(player).Cards.Count + PileType.Discard.GetPile(player).Cards.Count == 0)
			{
				ThinkCmd.Play(new LocString("combat_messages", "NO_DRAW"), player.Creature, 2.0);
				return false;
			}
			if (PileType.Hand.GetPile(player).Cards.Count >= CardPile.MaxCardsInHand)
			{
				ThinkCmd.Play(new LocString("combat_messages", "HAND_FULL"), player.Creature, 2.0);
				return false;
			}
			return true;
		}
	}
	public static class CardSelectCmd
	{
		private sealed class StackedSelectorScope : IDisposable
		{
			private readonly MegaCrit.Sts2.Core.TestSupport.ICardSelector _selector;

			private readonly Stack<MegaCrit.Sts2.Core.TestSupport.ICardSelector> _stack;

			private bool _disposed;

			public StackedSelectorScope(Stack<MegaCrit.Sts2.Core.TestSupport.ICardSelector> stack, MegaCrit.Sts2.Core.TestSupport.ICardSelector selector)
			{
				_stack = stack;
				_selector = selector;
			}

			public void Dispose()
			{
				if (!_disposed)
				{
					_disposed = true;
					if (_stack.Count > 0 && _stack.Peek() == _selector)
					{
						_stack.Pop();
					}
				}
			}
		}

		private sealed class NoOpScope : IDisposable
		{
			public void Dispose()
			{
			}
		}

		private sealed class RestoreSelectorScope : IDisposable
		{
			private readonly Stack<MegaCrit.Sts2.Core.TestSupport.ICardSelector> _stack;

			private readonly MegaCrit.Sts2.Core.TestSupport.ICardSelector _saved;

			private bool _disposed;

			public RestoreSelectorScope(Stack<MegaCrit.Sts2.Core.TestSupport.ICardSelector> stack, MegaCrit.Sts2.Core.TestSupport.ICardSelector saved)
			{
				_stack = stack;
				_saved = saved;
			}

			public void Dispose()
			{
				if (!_disposed)
				{
					_disposed = true;
					_stack.Push(_saved);
				}
			}
		}

		private sealed class SelectorScope : IDisposable
		{
			private readonly Stack<MegaCrit.Sts2.Core.TestSupport.ICardSelector> _stack;

			private bool _disposed;

			public SelectorScope(Stack<MegaCrit.Sts2.Core.TestSupport.ICardSelector> stack)
			{
				_stack = stack;
			}

			public void Dispose()
			{
				if (!_disposed)
				{
					_disposed = true;
					_stack.Clear();
				}
			}
		}

		private static readonly Stack<MegaCrit.Sts2.Core.TestSupport.ICardSelector> _selectorStack = new Stack<MegaCrit.Sts2.Core.TestSupport.ICardSelector>();

		private static readonly Stack<MegaCrit.Sts2.Core.TestSupport.ICardSelector> _localSelectorStack = new Stack<MegaCrit.Sts2.Core.TestSupport.ICardSelector>();

		public static MegaCrit.Sts2.Core.TestSupport.ICardSelector? Selector
		{
			get
			{
				if (_selectorStack.Count <= 0)
				{
					return null;
				}
				return _selectorStack.Peek();
			}
		}

		public static MegaCrit.Sts2.Core.TestSupport.ICardSelector? LocalSelector
		{
			get
			{
				if (_localSelectorStack.Count <= 0)
				{
					return null;
				}
				return _localSelectorStack.Peek();
			}
		}

		public static void Reset()
		{
			if (!TestMode.IsOn && (_selectorStack.Count > 0 || _localSelectorStack.Count > 0))
			{
				Log.Warn($"CardSelectCmd.Reset: clearing {_selectorStack.Count}/{_localSelectorStack.Count} leaked selector(s) from the stack.");
				_selectorStack.Clear();
				_localSelectorStack.Clear();
			}
		}

		public static IDisposable UseSelector(MegaCrit.Sts2.Core.TestSupport.ICardSelector selector, bool localOnly = false)
		{
			Stack<MegaCrit.Sts2.Core.TestSupport.ICardSelector> stack = (localOnly ? _localSelectorStack : _selectorStack);
			if (stack.Count > 0)
			{
				throw new InvalidOperationException("A card selector is already active.");
			}
			stack.Push(selector);
			return new SelectorScope(stack);
		}

		public static IDisposable PushSelector(MegaCrit.Sts2.Core.TestSupport.ICardSelector selector, bool localOnly = false)
		{
			Stack<MegaCrit.Sts2.Core.TestSupport.ICardSelector> stack = (localOnly ? _localSelectorStack : _selectorStack);
			stack.Push(selector);
			return new StackedSelectorScope(stack, selector);
		}

		public static IDisposable SuspendSelectorForTest(bool localOnly = false)
		{
			Stack<MegaCrit.Sts2.Core.TestSupport.ICardSelector> stack = (localOnly ? _localSelectorStack : _selectorStack);
			if (stack.Count == 0)
			{
				return new NoOpScope();
			}
			MegaCrit.Sts2.Core.TestSupport.ICardSelector saved = stack.Pop();
			return new RestoreSelectorScope(stack, saved);
		}

		private static bool ShouldSelectLocalCard(Player player)
		{
			if (LocalContext.IsMe(player))
			{
				return RunManager.Instance.NetService.Type != NetGameType.Replay;
			}
			return false;
		}

		private static void ReportSoftlock()
		{
			string text = "A selection screen was about to be shown with 0 options. Returning empty to prevent softlock.";
			Log.Error(text);
			SentryService.CaptureException(new SoftlockException(text));
		}

		public static async Task<CardModel?> FromChooseACardScreen(PlayerChoiceContext context, IReadOnlyList<CardModel> cards, Player player, bool canSkip = false)
		{
			if (cards.Count > 3)
			{
				throw new ArgumentException("Only works with less than 3 cards", "cards");
			}
			if (cards.Count == 0)
			{
				ReportSoftlock();
				return null;
			}
			UndoEndTurnIfNecessary(player);
			CardModel result;
			if (Selector != null)
			{
				result = (await Selector.GetSelectedCards(cards, 0, 1)).FirstOrDefault();
			}
			else
			{
				uint choiceId = RunManager.Instance.PlayerChoiceSynchronizer.ReserveChoiceId(player);
				await context.SignalPlayerChoiceBegun(player, PlayerChoiceOptions.None);
				if (ShouldSelectLocalCard(player))
				{
					if (LocalSelector != null)
					{
						result = (await LocalSelector.GetSelectedCards(cards, 0, 1)).FirstOrDefault();
					}
					else
					{
						NPlayerHand.Instance?.CancelAllCardPlay();
						NChooseACardSelectionScreen nChooseACardSelectionScreen = NChooseACardSelectionScreen.ShowScreen(cards, canSkip);
						if (LocalContext.IsMe(player))
						{
							foreach (CardModel card in cards)
							{
								SaveManager.Instance.MarkCardAsSeen(card);
							}
						}
						result = (await nChooseACardSelectionScreen.CardsSelected()).FirstOrDefault();
						int value = cards.IndexOf(result);
						PlayerChoiceResult result2 = PlayerChoiceResult.FromIndex(value);
						RunManager.Instance.PlayerChoiceSynchronizer.SyncLocalChoice(player, choiceId, result2);
					}
				}
				else
				{
					int num = (await RunManager.Instance.PlayerChoiceSynchronizer.WaitForRemoteChoice(player, choiceId)).AsIndex();
					result = ((num < 0) ? null : cards[num]);
				}
				await context.SignalPlayerChoiceEnded();
			}
			LogChoice(player, new global::<>z__ReadOnlySingleElementList<CardModel>(result));
			return result;
		}

		public static async Task<IEnumerable<CardModel>> FromSimpleGridForRewards(PlayerChoiceContext context, List<CardCreationResult> cards, Player player, CardSelectorPrefs prefs)
		{
			if (CombatManager.Instance.IsEnding)
			{
				return Array.Empty<CardModel>();
			}
			UndoEndTurnIfNecessary(player);
			if (cards.Count == 0)
			{
				ReportSoftlock();
				return Array.Empty<CardModel>();
			}
			uint? choiceId = null;
			if (Selector == null)
			{
				choiceId = RunManager.Instance.PlayerChoiceSynchronizer.ReserveChoiceId(player);
				await context.SignalPlayerChoiceBegun(player, PlayerChoiceOptions.None);
			}
			List<CardModel> result;
			if (!prefs.RequireManualConfirmation && cards.Count <= prefs.MinSelect)
			{
				result = cards.Select((CardCreationResult c) => c.Card).ToList();
			}
			else if (Selector != null)
			{
				IEnumerable<CardModel> options = cards.Select((CardCreationResult c) => c.Card);
				result = (await Selector.GetSelectedCards(options, prefs.MinSelect, prefs.MaxSelect)).ToList();
			}
			else if (ShouldSelectLocalCard(player))
			{
				if (LocalSelector != null)
				{
					IEnumerable<CardModel> options2 = cards.Select((CardCreationResult c) => c.Card);
					result = (await LocalSelector.GetSelectedCards(options2, prefs.MinSelect, prefs.MaxSelect)).ToList();
				}
				else
				{
					NSimpleCardSelectScreen nSimpleCardSelectScreen = NSimpleCardSelectScreen.Create(cards, prefs);
					NOverlayStack.Instance.Push(nSimpleCardSelectScreen);
					result = (await nSimpleCardSelectScreen.CardsSelected()).ToList();
					List<int> indexes = result.Select((CardModel c) => cards.FindIndex((CardCreationResult r) => r.Card == c)).ToList();
					RunManager.Instance.PlayerChoiceSynchronizer.SyncLocalChoice(player, choiceId.Value, PlayerChoiceResult.FromIndexes(indexes));
				}
			}
			else
			{
				result = (from i in (await RunManager.Instance.PlayerChoiceSynchronizer.WaitForRemoteChoice(player, choiceId.Value)).AsIndexes()
					select cards[i].Card).ToList();
			}
			if (choiceId.HasValue)
			{
				await context.SignalPlayerChoiceEnded();
			}
			LogChoice(player, result);
			return result;
		}

		public static async Task<IEnumerable<CardModel>> FromSimpleGrid(PlayerChoiceContext context, IReadOnlyList<CardModel> cardsIn, Player player, CardSelectorPrefs prefs)
		{
			if (CombatManager.Instance.IsEnding)
			{
				return Array.Empty<CardModel>();
			}
			UndoEndTurnIfNecessary(player);
			List<CardModel> cards = cardsIn.ToList();
			uint? choiceId = null;
			if (Selector == null)
			{
				choiceId = RunManager.Instance.PlayerChoiceSynchronizer.ReserveChoiceId(player);
				await context.SignalPlayerChoiceBegun(player, PlayerChoiceOptions.None);
			}
			List<CardModel> result;
			if (cards.Count == 0)
			{
				result = new List<CardModel>();
			}
			else if (!prefs.RequireManualConfirmation && cards.Count <= prefs.MinSelect)
			{
				result = cards.ToList();
			}
			else if (Selector != null)
			{
				result = (await Selector.GetSelectedCards(cards, prefs.MinSelect, prefs.MaxSelect)).ToList();
			}
			else if (ShouldSelectLocalCard(player))
			{
				if (LocalSelector != null)
				{
					result = (await LocalSelector.GetSelectedCards(cards, prefs.MinSelect, prefs.MaxSelect)).ToList();
				}
				else
				{
					NPlayerHand.Instance?.CancelAllCardPlay();
					NSimpleCardSelectScreen nSimpleCardSelectScreen = NSimpleCardSelectScreen.Create(cards, prefs);
					NOverlayStack.Instance.Push(nSimpleCardSelectScreen);
					result = (await nSimpleCardSelectScreen.CardsSelected()).ToList();
					List<int> indexes = result.Select((CardModel c) => cards.IndexOf(c)).ToList();
					RunManager.Instance.PlayerChoiceSynchronizer.SyncLocalChoice(player, choiceId.Value, PlayerChoiceResult.FromIndexes(indexes));
				}
			}
			else
			{
				result = (from i in (await RunManager.Instance.PlayerChoiceSynchronizer.WaitForRemoteChoice(player, choiceId.Value)).AsIndexes()
					select cards[i]).ToList();
			}
			if (choiceId.HasValue)
			{
				await context.SignalPlayerChoiceEnded();
			}
			LogChoice(player, result);
			return result;
		}

		public static async Task<IEnumerable<CardModel>> FromCombatPile(PlayerChoiceContext context, CardPile pile, Player player, CardSelectorPrefs prefs)
