			{
				result = (await Selector.GetSelectedCards(list, 1, 1)).FirstOrDefault();
			}
			else if (ShouldSelectLocalCard(player))
			{
				if (LocalSelector != null)
				{
					result = (await LocalSelector.GetSelectedCards(list, 1, 1)).FirstOrDefault();
