		public static async Task<IEnumerable<CardModel>> FromChooseABundleScreen(Player player, IReadOnlyList<IReadOnlyList<CardModel>> bundles)
		{
			if (CombatManager.Instance.IsEnding)
			{
				return Array.Empty<CardModel>();
			}
			if (bundles.Count == 0)
			{
				ReportSoftlock();
				return Array.Empty<CardModel>();
			}
			uint choiceId = RunManager.Instance.PlayerChoiceSynchronizer.ReserveChoiceId(player);
			IReadOnlyList<CardModel> readOnlyList;
			if (TestMode.IsOn)
			{
				readOnlyList = bundles[0];
			}
			else if (ShouldSelectLocalCard(player))
			{
				NChooseABundleSelectionScreen nChooseABundleSelectionScreen = NChooseABundleSelectionScreen.ShowScreen(bundles);
				readOnlyList = (await nChooseABundleSelectionScreen.CardsSelected()).FirstOrDefault() ?? Array.Empty<CardModel>();
				RunManager.Instance.PlayerChoiceSynchronizer.SyncLocalChoice(player, choiceId, PlayerChoiceResult.FromIndex(bundles.IndexOf<IReadOnlyList<CardModel>>(readOnlyList)));
			}
			else
			{
				int num = (await RunManager.Instance.PlayerChoiceSynchronizer.WaitForRemoteChoice(player, choiceId)).AsIndex();
				IReadOnlyList<CardModel> readOnlyList2;
				if (num >= 0)
				{
					readOnlyList2 = bundles[num];
				}
				else
				{
					IReadOnlyList<CardModel> readOnlyList3 = Array.Empty<CardModel>();
					readOnlyList2 = readOnlyList3;
				}
				readOnlyList = readOnlyList2;
			}
			LogChoice(player, readOnlyList);
			return readOnlyList;
		}

		private static void LogChoice(Player player, IEnumerable<CardModel?> cards)
		{
			string value = string.Join(",", from c in cards.OfType<CardModel>()
				select c.Id.Entry);
			Log.Info($"Player {player.NetId} chose cards [{value}]");
		}

		private static void UndoEndTurnIfNecessary(Player player)
		{
			if (CombatManager.Instance.IsPlayerReadyToEndTurn(player) && player.Creature.CombatState != null && player.Creature.CombatState.CurrentSide == CombatSide.Player)
			{
				CombatManager.Instance.UndoReadyToEndTurn(player);
			}
		}
	}
	public static class Cmd
	{
		public static Task Wait(float seconds, bool ignoreCombatEnd = false)
		{
			return Wait(seconds, default(CancellationToken), ignoreCombatEnd);
		}

		public static async Task Wait(float seconds, CancellationToken cancelToken, bool ignoreCombatEnd = false)
		{
			if (!NonInteractiveMode.IsActive && !(seconds <= 0f) && (NGame.Instance == null || (SaveManager.Instance.PrefsSave.FastMode != FastModeType.Instant && (ignoreCombatEnd || !CombatManager.Instance.IsEnding))))
			{
				SceneTree val = (SceneTree)Engine.GetMainLoop();
				SceneTreeTimer timer = val.CreateTimer((double)seconds, true, false, false);
				await WaitInternal(timer, cancelToken);
			}
		}

		private static async Task WaitInternal(SceneTreeTimer timer, CancellationToken cancellationToken)
		{
			await ((GodotObject)timer).ToSignal((GodotObject)(object)timer, SignalName.Timeout).ToTask().WaitAsync(cancellationToken);
		}

		public static async Task CustomScaledWait(float fastSeconds, float standardSeconds, bool ignoreCombatEnd = false, CancellationToken cancellationToken = default(CancellationToken))
		{
			if (!NonInteractiveMode.IsActive && SaveManager.Instance.PrefsSave.FastMode != FastModeType.Instant && (ignoreCombatEnd || !CombatManager.Instance.IsEnding))
			{
				switch (SaveManager.Instance.PrefsSave.FastMode)
				{
				case FastModeType.Fast:
					await Wait(fastSeconds, cancellationToken, ignoreCombatEnd);
					break;
				case FastModeType.Normal:
					await Wait(standardSeconds, cancellationToken, ignoreCombatEnd);
					break;
				default:
					throw new ArgumentOutOfRangeException();
				case FastModeType.Instant:
					break;
				}
			}
		}
	}
	public static class CreatureCmd
	{
		public static async Task<Creature> Add<T>(ICombatState combatState, string? slotName = null) where T : MonsterModel
		{
			Creature creature = combatState.CreateCreature(ModelDb.Monster<T>().ToMutable(), CombatSide.Enemy, slotName);
			await Add(creature);
			return creature;
		}

		public static async Task<Creature> Add(MonsterModel monster, ICombatState combatState, CombatSide side = CombatSide.Enemy, string? slotName = null)
		{
			monster.AssertMutable();
			Creature creature = combatState.CreateCreature(monster, side, slotName);
			await Add(creature);
			return creature;
		}

		public static async Task Add(Creature creature)
		{
			if (!CombatManager.Instance.IsInProgress)
			{
				throw new InvalidOperationException("Attempted to add a creature outside of combat.");
			}
			ICombatState combatState = creature.CombatState;
			if (combatState == null)
			{
				throw new InvalidOperationException("Attempted to add a creature with no combat state.");
			}
			if (!combatState.IsLiveCombat())
			{
				return;
			}
			combatState.AddCreature(creature);
			CombatManager.Instance.AddCreature(creature);
			NCombatRoom.Instance?.AddCreature(creature);
			await CombatManager.Instance.AfterCreatureAdded(creature);
			if (combatState.CurrentSide != CombatSide.Enemy && creature.IsMonster)
			{
				creature.PrepareForNextTurn(combatState.Players.Select((Player p) => p.Creature), rollNewMove: false);
			}
			MapPointRoomHistoryEntry mapPointRoomHistoryEntry = combatState.RunState.CurrentMapPointHistoryEntry?.Rooms.Last();
			if (mapPointRoomHistoryEntry != null && creature != null && creature.Monster != null && creature.Side == CombatSide.Enemy && !mapPointRoomHistoryEntry.MonsterIds.Contains(creature.Monster.Id))
			{
				mapPointRoomHistoryEntry.MonsterIds.Add(creature.Monster.Id);
			}
			await Hook.AfterCreatureAddedToCombat(creature.CombatState, creature);
		}

