	public class OrbChanneledEntry : CombatHistoryEntry
	{
		public OrbModel Orb { get; }

		public override string Description => base.Actor.Player.Character.Id.Entry + " channeled " + Orb.Id.Entry;

		public OrbChanneledEntry(OrbModel orb, int roundNumber, CombatSide currentSide, CombatHistory history, IEnumerable<Player> players)
			: base(orb.Owner.Creature, roundNumber, currentSide, history, players)
		{
			Orb = orb;
		}
	}
	public class PotionUsedEntry : CombatHistoryEntry
	{
		public PotionModel Potion { get; }

		public Creature? Target { get; }

		public override string Description
		{
			get
			{
				StringBuilder stringBuilder = new StringBuilder(base.Actor.Player.Character.Id.Entry + " drank " + Potion.Id.Entry);
				if (Target != null)
				{
					StringBuilder stringBuilder2 = stringBuilder;
					StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(11, 1, stringBuilder2);
					handler.AppendLiteral(" targeting ");
					handler.AppendFormatted(Target.Monster.Id.Entry);
					stringBuilder2.Append(ref handler);
				}
				return stringBuilder.ToString();
			}
		}

		public PotionUsedEntry(PotionModel potion, Creature? target, int roundNumber, CombatSide currentSide, CombatHistory history, IEnumerable<Player> players)
			: base(potion.Owner.Creature, roundNumber, currentSide, history, players)
		{
			Potion = potion;
			Target = target;
		}
	}
	public class PowerReceivedEntry : CombatHistoryEntry
	{
		public PowerModel Power { get; }

		public decimal Amount { get; }

		public Creature? Applier { get; }

		public override string Description
		{
			get
			{
				if (Applier == null)
				{
					return $"{base.Actor.ModelId.Entry} received {Amount} {Power.Id.Entry}";
				}
				return $"{Applier.ModelId.Entry} applied {Amount} {Power.Id.Entry} to {base.Actor.ModelId.Entry}";
			}
		}

		public PowerReceivedEntry(PowerModel power, decimal amount, Creature? applier, int roundNumber, CombatSide currentSide, CombatHistory history, IEnumerable<Player> players)
			: base(power.Owner, roundNumber, currentSide, history, players)
		{
			Power = power;
			Amount = amount;
			Applier = applier;
		}
	}
	public class StarsModifiedEntry(int amount, Player player, int roundNumber, CombatSide currentSide, CombatHistory history, IEnumerable<Player> players) : CombatHistoryEntry(player.Creature, roundNumber, currentSide, history, players)
	{
		public int Amount { get; } = amount;

		public override string Description => $"{base.Actor.Player.Character.Id.Entry} {((Amount < 0) ? "lost" : "gained")} {Amount} star(s)";
	}
	public class SummonedEntry(int amount, Player player, int roundNumber, CombatSide currentSide, CombatHistory history, IEnumerable<Player> players) : CombatHistoryEntry(player.Creature, roundNumber, currentSide, history, players)
	{
		public int Amount { get; } = amount;

		public override string Description => $"{base.Actor.Player.Character.Id.Entry} summoned {Amount}";
	}
