			value = Math.Clamp(value, 0.1, 4.0);
			Engine.TimeScale = value;
			((Node)(object)this).AddChildSafely((Node?)(object)NFullscreenTextVfx.Create($"TimeScale:{Engine.TimeScale}"));
		}

