					_proceedButton.SetPulseState(isPulsing: true);
					_rewardsContainer.FocusMode = (FocusModeEnum)0;
					IsComplete = true;
					((GodotObject)this).EmitSignal(SignalName.Completed, Array.Empty<Variant>());
