			{
				return $"res://images/atlases/era_atlas.sprites/era_{(int)era}.tres";
			}
			return $"res://images/atlases/era_atlas.sprites/era_minus_{Math.Abs((int)era)}.tres";
		}

		private static IEnumerable<string> GetAllEraTexturePaths()
