			NAspectRatioDropdownItem nAspectRatioDropdownItem = ResourceLoader.Load<PackedScene>(AspectRatioDropdownItemScenePath, (string)null, (CacheMode)1).Instantiate<NAspectRatioDropdownItem>((GenEditState)0);
