		{
			_settingsScreen.ShowToast(new LocString("settings_ui", "TOAST_HAND_CARD_COUNT_OFF"));
			SaveManager.Instance.PrefsSave.ShowCardIndices = false;
			TryRefreshHandIndices();
		}

