				SwitchTabTo(list[num]);
			}
		}

		private void TabRight()
		{
			List<NSettingsTab> list = _tabs.Keys.ToList();
			int num = Math.Min(list.Count - 1, list.IndexOf(_currentTab) + 1);
			if (num < list.Count)
