		public static IEnumerable<string> AssetPaths => new global::<>z__ReadOnlyArray<string>(new string[2] { _scenePath, "res://scenes/screens/custom_run/modifier_tickbox.tscn" });

		protected override Control? InitialFocusedControl => null;

		public static NCustomRunLoadScreen? Create()
		{
			if (TestMode.IsOn)
			{
				return null;
			}
			return PreloadManager.Cache.GetScene(_scenePath).Instantiate<NCustomRunLoadScreen>((GenEditState)0);
		}

