		{
			if (_lobby.NetService.Type == NetGameType.Client)
			{
				((CanvasItem)_ascensionPanel).Visible = _lobby.Ascension > 0;
			}
			_ascensionPanel.SetAscensionLevel(_lobby.Ascension);
		}

