		private void UpdatePileContents()
		{
			IReadOnlyList<CardModel> readOnlyList;
			if (_filter == null)
			{
				readOnlyList = _pile.Cards;
			}
			else
			{
				IReadOnlyList<CardModel> readOnlyList2 = _pile.Cards.Where(_filter).ToList();
