		private void EnableStatsModeHotkeys()
		{
			NHotkeyManager.Instance.PushHotkeyPressedBinding(StringName.op_Implicit(_filterLeftHotkey), FilterLeft);
			NHotkeyManager.Instance.PushHotkeyPressedBinding(StringName.op_Implicit(_filterRightHotkey), FilterRight);
		}

		private void DisableStatsModeHotkeys()
		{
			NHotkeyManager.Instance.RemoveHotkeyPressedBinding(StringName.op_Implicit(_filterLeftHotkey), FilterLeft);
			NHotkeyManager.Instance.RemoveHotkeyPressedBinding(StringName.op_Implicit(_filterRightHotkey), FilterRight);
		}

		private void FilterLeft()
		{
			List<NBestiaryCharacterFilter> list = ((IEnumerable)((Node)_filterContainer).GetChildren(false)).OfType<NBestiaryCharacterFilter>().ToList();
			int num = list.IndexOf(_currentFilter);
			for (int i = 1; i <= list.Count; i++)
			{
				int index = (num - i + list.Count) % list.Count;
				if (!list[index].IsLocked)
				{
					SelectFilter(list[index]);
					break;
				}
			}
		}

		private void FilterRight()
		{
			List<NBestiaryCharacterFilter> list = ((IEnumerable)((Node)_filterContainer).GetChildren(false)).OfType<NBestiaryCharacterFilter>().ToList();
			int num = list.IndexOf(_currentFilter);
			for (int i = 1; i <= list.Count; i++)
			{
				int index = (num + i) % list.Count;
				if (!list[index].IsLocked)
				{
					SelectFilter(list[index]);
					break;
				}
			}
		}

		private void SelectFilter(NBestiaryCharacterFilter filter)
		{
			filter.IsSelected = true;
			OnCharacterFilterSelected(filter);
		}

		private void UpdatePageIcons()
		{
			bool flag = _isStatsMode && NControllerManager.Instance.IsUsingDirectionalNavigation;
			((CanvasItem)_pageLeftIcon).Visible = flag;
			((CanvasItem)_pageRightIcon).Visible = flag;
			if (flag)
			{
				_pageLeftIcon.UpdateInput(StringName.op_Implicit(MegaInput.viewDeckAndTabLeft));
				_pageRightIcon.UpdateInput(StringName.op_Implicit(MegaInput.viewExhaustPileAndTabRight));
			}
		}

		public static bool CanBeShown()
		{
			if (SaveManager.Instance.Progress.DiscoveredActs.Count == 0)
			{
				return false;
			}
			return SaveManager.Instance.Progress.EnemyStats.Values.Any((EnemyStats e) => e.TotalWins > 0);
		}

