		{
			if (TestMode.IsOn)
			{
				return null;
			}
			NBestiaryLayoutDecimillipede nBestiaryLayoutDecimillipede = PreloadManager.Cache.GetScene(_scenePath).Instantiate<NBestiaryLayoutDecimillipede>((GenEditState)0);
