					int value2 = monster.Creature.MonsterMaxHpBeforeModification.Value;
					float num = ((monster.MaxInitialHp != monster.MinInitialHp) ? (((float)(value2 - monster.MinInitialHp) / (float)(monster.MaxInitialHp - monster.MinInitialHp) - 0.5f) * 2f) : 0f);
					num = Mathf.Clamp(num, 0f, 1f);
