					float amount = Mathf.Clamp(Mathf.InverseLerp(250f, 100f, num2), 0f, 1f);
					float num3 = float.Lerp(0.1f, 0.15f, amount);
					item2.SetScaleAndHue(1f + num * num3, Rng.Chaotic.NextFloat(0.05f));
