			val2.SetParallel(false);
			val2.TweenProperty((GodotObject)(object)this, NodePath.op_Implicit("modulate:a"), Variant.op_Implicit(0f), 0.20000000298023224).SetDelay(0.6000000238418579).SetEase((EaseType)0)
