			if (line != null)
			{
				await Cmd.Wait(0.75f, _cts.Token);
				SfxCmd.Play("event:/sfx/npcs/reverse_merchant/reverse_merchant_laugh");
				MerchantButton.PlayDialogue(line, 4.0);
			}
		}

