			_fadeTween.TweenProperty((GodotObject)(object)this, NodePath.op_Implicit("modulate:a"), Variant.op_Implicit(1.0), 0.5).From(Variant.op_Implicit(0f));
			_fadeTween.Chain().TweenCallback(Callable.From((Action)delegate
			{
