				AnimEnable();
			}
		}

		private void OnCombatStateChanged(CombatState state)
		{
			_combatState = state;
			if (IsInCardSelection)
			{
				RevalidateSelectionAfterStateChange();
			}
			foreach (NHandCardHolder holder in Holders)
			{
				holder.UpdateCard();
