							{
								text = "[",
								type = BbcodeObjectType.Text
							});
						}
						else if (text2 == "rb")
						{
							_cachedBbcodeObjects.Add(new BbcodeObject
							{
								text = "]",
								type = BbcodeObjectType.Text
							});
						}
						else
						{
